'use strict';
(function () {
  // ================= helpers =================
  const NS = 'http://www.w3.org/2000/svg';
  const $ = (id) => document.getElementById(id);
  const F = (s, o) => String(s).replace(/\{(\w+)\}/g, (m, k) => (o && o[k] !== undefined ? o[k] : m));
  function mk(tag, attrs, parent) {
    const e = document.createElementNS(NS, tag);
    if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }
  function txt(parent, x, y, str, attrs) {
    const t = mk('text', Object.assign({ x: x, y: y }, attrs || {}), parent);
    t.textContent = str;
    return t;
  }
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = (a) => a[(Math.random() * a.length) | 0];
  const r1 = (n) => Math.round(n * 10) / 10;
  const r3 = (n) => Math.round(n * 1000) / 1000;
  const fmt = (n) => String(Math.max(0, Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const show = (el, on) => { if (typeof el === 'string') el = $(el); if (el) el.style.display = on ? '' : 'none'; };
  const setText = (el, s) => { s = String(s); if (el.__t !== s) { el.__t = s; el.textContent = s; } };
  const easeOutBack = (k) => { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2); };
  const easeInCubic = (k) => k * k * k;

  // ================= constants =================
  const FX0 = 280, FX1 = 1000, FY0 = 28;
  const COLS = 17, CW = 40, CH = 30, BW = 36, BH = 26;
  const GX0 = 320, GY0 = 85;
  const PADDLE_Y = 652, PADDLE_TOP = 643;
  const R = 9;
  const MAX_BALLS = 12, TRAIL_N = 14;
  const MAX_ANGLE = 62 * Math.PI / 180;
  const BEAN = 'M-11,0 C-11,-7 -5,-8.6 0,-6 C5,-8.6 11,-7 11,0 C11,6.5 5.5,8 0,8 C-5.5,8 -11,6.5 -11,0 Z';
  const BEAN_HL = 'M-7.5,-2.6 C-6.8,-5.8 -2.6,-6.4 -0.6,-4.8 C-2.8,-3.6 -5.4,-3 -7.5,-2.6 Z';
  const HEART = 'M0,12 C-15,3 -18,-10 -10,-14.5 C-5,-17 -1.5,-13.5 0,-10.5 C1.5,-13.5 5,-17 10,-14.5 C18,-10 15,3 0,12 Z';
  const SPIRAL = 'M0,0 a2,2 0 0 1 4,0 a4,4 0 0 1 -8,0 a6,6 0 0 1 12,0 a8,8 0 0 1 -16,0';

  const DIFF = {
    easy: { name: S.diffEasy, desc: S.descEasy, speed: 390, paddle: 138, bad: 0.12, par: 1.3, base: '#57d3a7', deep: '#23a077' },
    normal: { name: S.diffNormal, desc: S.descNormal, speed: 470, paddle: 114, bad: 0.24, par: 1.0, base: '#ff8fbd', deep: '#d9477f' },
    hard: { name: S.diffHard, desc: S.descHard, speed: 565, paddle: 96, bad: 0.4, par: 0.85, base: '#ff9f5a', deep: '#d9642a' },
  };
  const DIFF_KEYS = ['easy', 'normal', 'hard'];

  const COLORS = {
    P: { id: 'P', base: '#ff8fbd', light: '#ffd3e5', deep: '#dd4f8b' },
    M: { id: 'M', base: '#6fe0b9', light: '#cbf7e7', deep: '#28ae84' },
    Y: { id: 'Y', base: '#ffd86e', light: '#fff2c2', deep: '#e0a52a' },
    L: { id: 'L', base: '#b9a0ff', light: '#e6ddff', deep: '#7f60e3' },
    O: { id: 'O', base: '#ffac7f', light: '#ffdcc8', deep: '#e3773f' },
    B: { id: 'B', base: '#88cefb', light: '#d5eeff', deep: '#4497db' },
    R: { id: 'R', base: '#ff7088', light: '#ffc2cc', deep: '#d6385a' },
    W: { id: 'W', base: '#fff5ea', light: '#ffffff', deep: '#dcb9a3' },
    G: { id: 'G', base: '#b6e46c', light: '#e5f8c3', deep: '#78b02c' },
    N: { id: 'N', base: '#e6a86a', light: '#f8d7ad', deep: '#b06e36' },
    D: { id: 'D', base: '#b57d58', light: '#deb392', deep: '#7b4c30' },
    '3': { id: 'ruby', base: '#f2557d', light: '#ffb3c6', deep: '#b0244d' },
    '4': { id: 'ame', base: '#a36cf2', light: '#dcc5ff', deep: '#6a3bb6' },
    X: { id: 'choco', base: '#7c4b33', light: '#a8714f', deep: '#452617' },
    '*': { id: 'pop', base: '#c78bff', light: '#f1ddff', deep: '#8747d6' },
    '@': { id: 'gift', base: '#fff1c4', light: '#fffbea', deep: '#e3ac45' },
  };

  const LEVELS = [
    { name: S.lv1, tip: S.lv1t, par: 150, rows: [
      '..RRR...RRR..',
      '.RPPPR.RPPPR.',
      'RPWWPPRPP@PPR',
      'RPWPP*PPPPPPR',
      'RPPP@PPPP*PPR',
      '.RPPPP*PPPPR.',
      '..RPPPPPP@R..',
      '...RPP*PPR...',
      '....RPPPR....',
      '.....RPR.....',
      '......R......',
    ] },
    { name: S.lv2, tip: S.lv2t, par: 170, rows: [
      '........P........',
      '.......PPP.......',
      'M.M...PPPPP...M.M',
      'MMM...YYYYY...MMM',
      'MXM...Y*X*Y...MXM',
      'MMM...YYYYY...MMM',
      'MMMW.WY@Y@YW.WMMM',
      'MMMWWWWWWWWWWWMMM',
      'mmmW@WWXXXWW@Wmmm',
      'mmmWWWX...XWWWmmm',
    ] },
    { name: S.lv3, tip: S.lv3t, par: 170, rows: [
      '......ppppp......',
      '....ppMMMMMpp....',
      '...pMMYYYYYMMp...',
      '...pMYYLLLYYMp...',
      '...pMYL@*@LYMp...',
      '...pMYYLLLYYMp...',
      '...pMMYYYYYMMp...',
      '.B..ppMMMMMpp..O.',
      'BYB...ppppp...OMO',
      '.B......X......O.',
      '.W......W......W.',
      '.W......W......W.',
    ] },
    { name: S.lv4, tip: S.lv4t, par: 180, rows: [
      '.....NNNNNNN.....',
      '...NNNWNNNWNNN...',
      '..NNWNNN@NNNWNN..',
      '..NNNNNNNNNNNNN..',
      '....GGGG*GGGG....',
      '...YYYYY@YYYYY...',
      '..ddddddddddddd..',
      '....RRR*R*RRR....',
      '..NNNNNNNNNNNNN..',
      '...NNNNNNNNNNN...',
    ], moves: [
      { rows: [4], amp: 130, speed: 1.2, phase: 0 },
      { rows: [5], amp: 110, speed: 1.2, phase: Math.PI },
      { rows: [7], amp: 130, speed: 0.9, phase: 1.6 },
    ] },
    { name: S.lv5, tip: S.lv5t, par: 170, rows: [
      '.nnn.....nnn.',
      'nPPNN...NNPPn',
      'nPNNNNNNNNNPn',
      '.NNNNN@NNNNN.',
      '.NNXNNNNNXNN.',
      '.NPPNNNNNPPN.',
      '.N*NWWWWWN*N.',
      '..NNWWXWWNN..',
      '...NW@*@WN...',
      '....NNNNN....',
    ] },
    { name: S.lv6, tip: S.lv6t, par: 180, rows: [
      '....ppppp....',
      '..ppYPPPMpp..',
      '.pBPPP*PPPLp.',
      '.PPMPnnnPPPP.',
      'pPLPn...nPYPp',
      'pYP@n...n@PPp',
      'pPPMn...nMPPp',
      '.NPPPnnnPPPN.',
      '.NNPYPP*PBNN.',
      '..NNNPPPNNN..',
      '....NNNNN....',
    ] },
    { name: S.lv7, tip: S.lv7t, par: 190, rows: [
      '........R........',
      '......PP*PP......',
      '.....PPPPPPP.....',
      '..MMMMPP@PPYYYY..',
      '.MMMMMMPPPYYYYYY.',
      '.MM*MMMM@YYYY*YY.',
      '..MMMMMWWWYYYYY..',
      '...WW@WWWWW@WW...',
      '....NnNnNnNnN....',
      '.....nNnNnNn.....',
      '......NnNnN......',
      '.......nNn.......',
      '........X........',
    ] },
    { name: S.lv8, tip: S.lv8t, par: 210, rows: [
      '......*.*.*......',
      '......Y.Y.Y......',
      '.....PPPPPPP.....',
      '.....L@LLL@L.....',
      '...WWWWWWWWWWW...',
      '...MMM*MMM*MMM...',
      '...mmmmmmmmmmm...',
      '.PPPPPPPPPPPPPPP.',
      '.YY@YY3YYY3YY@YY.',
      '.yyyyyyyyyyyyyyy.',
      'XXX...........XXX',
    ], moves: [
      { rows: [0, 1, 2, 3], amp: 170, speed: 0.85, phase: 0 },
      { rows: [4, 5, 6], amp: 110, speed: 0.85, phase: Math.PI },
    ] },
  ];

  const DROPS = {
    expand: { ch: S.chExpand, name: S.itExpand, desc: S.itExpandD, good: true, dur: 15, w: 1.0, base: '#48d6a4', light: '#c8f7e6', deep: '#1f9a72' },
    multi: { ch: S.chMulti, name: S.itMulti, desc: S.itMultiD, good: true, dur: 0, w: 1.15, base: '#56b8f7', light: '#d3edff', deep: '#2a7fc0' },
    slow: { ch: S.chSlow, name: S.itSlow, desc: S.itSlowD, good: true, dur: 12, w: 0.85, base: '#a58dff', light: '#e6ddff', deep: '#6d55d6' },
    laser: { ch: S.chLaser, name: S.itLaser, desc: S.itLaserD, good: true, dur: 8, w: 1.0, base: '#ff72b0', light: '#ffd3e5', deep: '#d23f80' },
    sticky: { ch: S.chSticky, name: S.itSticky, desc: S.itStickyD, good: true, dur: 15, w: 0.85, base: '#ffc54a', light: '#fff0c4', deep: '#c98410' },
    fire: { ch: S.chFire, name: S.itFire, desc: S.itFireD, good: true, dur: 8, w: 0.75, base: '#ff7a45', light: '#ffd8c4', deep: '#cf431c' },
    shrink: { ch: S.chShrink, name: S.itShrink, desc: S.itShrinkD, good: false, dur: 12, w: 1, base: '#8a7a9c', light: '#d5cce0', deep: '#51435f' },
    fast: { ch: S.chFast, name: S.itFast, desc: S.itFastD, good: false, dur: 10, w: 1, base: '#94607a', light: '#e2c4d2', deep: '#5a3044' },
  };
  const DROP_ORDER = ['expand', 'multi', 'slow', 'laser', 'sticky', 'fire', 'shrink', 'fast'];
  const GOOD_KEYS = ['expand', 'multi', 'slow', 'laser', 'sticky', 'fire'];
  const BAD_KEYS = ['shrink', 'fast'];
  const TIMED = ['laser', 'fire', 'sticky', 'expand', 'slow', 'shrink', 'fast'];

  // ================= save data =================
  const STORE = 'candy-breaker-save-v1';
  const save = { best: { easy: 0, normal: 0, hard: 0 }, diff: 'normal', muted: false };
  try {
    const s = JSON.parse(localStorage.getItem(STORE) || 'null');
    if (s) {
      if (s.best) for (const k of DIFF_KEYS) save.best[k] = Math.max(0, Number(s.best[k]) || 0);
      if (DIFF[s.diff]) save.diff = s.diff;
      save.muted = !!s.muted;
    }
  } catch (e) { /* storage unavailable */ }
  function persist() { try { localStorage.setItem(STORE, JSON.stringify(save)); } catch (e) { /* ignore */ } }

  // ================= audio =================
  const SONGS = {
    title: {
      bpm: 100, box: true,
      lead: [77, 0, 81, 84, 86, -1, 84, 81, 79, 0, 76, 79, 84, -1, 79, 76, 74, 0, 77, 81, 82, -1, 81, 77, 76, -1, -1, 0, 72, 74, 76, 79,
        77, 0, 81, 84, 89, -1, 88, 86, 84, 0, 81, 79, 81, -1, 77, 76, 74, 77, 82, 81, 79, -1, 77, 74, 72, -1, 76, -1, 77, -1, -1, 0],
      roots: [41, 48, 46, 48, 41, 45, 46, 48],
      chords: [[65, 69, 72], [64, 67, 72], [62, 65, 70], [64, 67, 72], [65, 69, 72], [64, 69, 72], [62, 65, 70], [60, 64, 67]],
      bass: [0, null, null, null, 7, null, null, null],
      drums: { k: 'x.......', s: '........', h: '..x...x.' },
    },
    game: {
      bpm: 140, box: false,
      lead: [76, 79, 84, 79, 81, 79, 76, 79, 76, 0, 72, 76, 81, 0, 79, 76, 77, 81, 84, 81, 86, 84, 81, 77, 79, 0, 83, 86, 91, -1, 89, 86,
        88, 86, 84, 79, 76, 79, 84, 88, 86, 84, 81, 76, 84, 83, 81, 0, 81, 84, 89, 88, 86, 84, 81, 77, 79, 83, 86, 83, 84, -1, -1, 0],
      roots: [48, 45, 41, 43, 48, 45, 38, 43],
      chords: [[60, 64, 67], [57, 60, 64], [53, 57, 60], [55, 59, 62], [60, 64, 67], [57, 60, 64], [50, 53, 57], [55, 59, 62]],
      bass: [0, null, 12, null, 7, null, 12, 7],
      drums: { k: 'x...x...', s: '..x...x.', h: 'xxxxxxxx' },
    },
  };

  const Snd = (function () {
    let ac = null, master = null, musicBus = null, sfxBus = null, noiseBuf = null, echo = null;
    let muted = false, song = null, songName = '', step = 0, nextT = 0;
    const last = {};
    const mtof = (m) => 440 * Math.pow(2, (m - 69) / 12);

    function init() {
      if (ac) { if (ac.state === 'suspended') ac.resume(); return; }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      try { ac = new AC(); } catch (e) { ac = null; return; }
      master = ac.createGain();
      master.gain.value = muted ? 0 : 0.85;
      const comp = ac.createDynamicsCompressor();
      comp.threshold.value = -14; comp.knee.value = 10; comp.ratio.value = 4;
      master.connect(comp); comp.connect(ac.destination);
      musicBus = ac.createGain(); musicBus.gain.value = 0.3; musicBus.connect(master);
      sfxBus = ac.createGain(); sfxBus.gain.value = 0.62; sfxBus.connect(master);
      echo = ac.createDelay(1); echo.delayTime.value = 0.3;
      const fb = ac.createGain(); fb.gain.value = 0.32;
      const eg = ac.createGain(); eg.gain.value = 0.4;
      echo.connect(fb); fb.connect(echo); echo.connect(eg); eg.connect(musicBus);
      noiseBuf = ac.createBuffer(1, ac.sampleRate, ac.sampleRate);
      const d = noiseBuf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      setInterval(tick, 25);
      if (songName) { song = SONGS[songName]; step = 0; nextT = ac.currentTime + 0.1; }
    }
    function tone(f, t0, dur, o) {
