    mk('rect', { x: x, y: y, width: BW, height: BH, rx: 8, fill: 'url(#gb-' + c.id + ')', 'fill-opacity': 0.8, stroke: c.deep, 'stroke-width': 1.6 }, g);
    mk('rect', { x: x + 1.8, y: y + 1.8, width: BW - 3.6, height: BH - 3.6, rx: 6.5, fill: 'none', stroke: c.light, 'stroke-width': 1.2, opacity: 0.7 }, g);
    mk('rect', { x: x + 4, y: y + BH - 9, width: BW - 8, height: 5, rx: 2.5, fill: c.light, opacity: 0.6 }, g);
    if (type === 'hard') {
      if (hp >= 3) {
        mk('path', { d: 'M0,-8 L10,0 L0,8 L-10,0 Z', fill: c.light, opacity: 0.55 }, g);
        mk('path', { d: 'M' + (x + 3) + ',' + (y + 3) + ' L-10,0 M' + (-x - 3) + ',' + (y + 3) + ' L10,0 M' + (x + 3) + ',' + (-y - 3) + ' L-10,0 M' + (-x - 3) + ',' + (-y - 3) + ' L10,0', stroke: '#fff', 'stroke-width': 1, opacity: 0.45 }, g);
      } else {
        mk('rect', { x: x, y: y, width: BW, height: BH, rx: 8, fill: 'url(#pat-hard)' }, g);
      }
      mk('rect', { x: x + 2.5, y: y + 2.5, width: BW - 5, height: BH - 5, rx: 6, fill: 'none', stroke: '#fff', 'stroke-width': 1.2, opacity: 0.6 }, g);
    }
    mk('rect', { x: x + 4, y: y + 3, width: BW - 8, height: 7, rx: 3.5, fill: '#fff', opacity: 0.62 }, g);
    mk('circle', { cx: x + 7.5, cy: y + 6.5, r: 1.7, fill: '#fff' }, g);
    if (type === 'pop') {
      mk('rect', { x: x + 2.5, y: y + 2.5, width: BW - 5, height: BH - 5, rx: 6, fill: 'none', stroke: '#fff', 'stroke-width': 1.2, 'stroke-dasharray': '3 3', opacity: 0.8 }, g);
      const cols = ['#ffffff', '#fff27a', '#7ff5ff', '#ff9ee6', '#b3ff9e'];
      for (let i = 0; i < 8; i++) {
        mk('circle', { cx: r1(rand(x + 5, -x - 5)), cy: r1(rand(y + 6, -y - 4)), r: r1(rand(1.2, 2.3)), fill: cols[i % cols.length], class: i % 2 ? 'tw' : '', style: 'animation-delay:' + r1(-rand(0, 1.6)) + 's' }, g);
      }
    }
    if (type === 'gift') {
      mk('rect', { x: -3.5, y: y, width: 7, height: BH, fill: '#ff6fa8', opacity: 0.92 }, g);
      mk('rect', { x: x, y: -3, width: BW, height: 6, fill: '#ff6fa8', opacity: 0.92 }, g);
      mk('path', { d: 'M0,' + (y + 1) + ' C-4,' + (y - 9) + ' -13,' + (y - 6) + ' -9,' + (y + 1) + ' Z', fill: '#ff8fbd', stroke: '#d6387a', 'stroke-width': 1.2 }, g);
      mk('path', { d: 'M0,' + (y + 1) + ' C4,' + (y - 9) + ' 13,' + (y - 6) + ' 9,' + (y + 1) + ' Z', fill: '#ff8fbd', stroke: '#d6387a', 'stroke-width': 1.2 }, g);
      mk('circle', { cx: 0, cy: y + 1, r: 2.8, fill: '#ff5c9d', stroke: '#d6387a', 'stroke-width': 1 }, g);
    }
    if (type === 'hard') {
      out.cracks = [];
      for (let lv = 1; lv <= 2; lv++) {
        const d = crackD(lv) + (lv === 2 ? crackD(1) : '');
        const cg = mk('g', { style: 'display:none' }, g);
        mk('path', { d: d, stroke: '#4a1230', 'stroke-width': lv === 2 ? 1.8 : 1.3, fill: 'none', opacity: 0.62, 'stroke-linejoin': 'round' }, cg);
        mk('path', { d: d, stroke: '#ffffff', 'stroke-width': 0.8, fill: 'none', opacity: 0.75, transform: 'translate(0.8,0.8)' }, cg);
        out.cracks.push(cg);
      }
    }
    out.flash = mk('rect', { x: x, y: y, width: BW, height: BH, rx: 8, fill: '#fff', opacity: 0 }, g);
    return out;
  }
  function buildBrick(k) {
    k.g = mk('g', { transform: 'translate(' + k.x + ',' + k.y + ')' }, L_bricks);
    const o = brickArt(k.g, k.type, k.color, k.hp);
    k.flash = o.flash;
    k.cracks = o.cracks || null;
  }
  function updateCracks(k) {
    if (!k.cracks) return;
    const stage = k.hp <= 1 ? 2 : (k.maxHp >= 3 && k.hp === 2 ? 1 : 0);
    show(k.cracks[0], stage === 1);
    show(k.cracks[1], stage === 2);
  }
  function parseCell(ch) {
    if (ch === 'X') return { type: 'choco', color: 'X', hp: 1e9 };
    if (ch === '*') return { type: 'pop', color: '*', hp: 1 };
    if (ch === '@') return { type: 'gift', color: '@', hp: 1 };
    if (ch === '3' || ch === '4') return { type: 'hard', color: ch, hp: 3 };
    const up = ch.toUpperCase();
    if (/[A-Z]/.test(up) && COLORS[up]) return ch === up ? { type: 'normal', color: up, hp: 1 } : { type: 'hard', color: up, hp: 2 };
    return null;
  }

  // ================= drop visuals =================
  function dropArt(parent, type, s) {
    const D = DROPS[type];
    const g = mk('g', s && s !== 1 ? { transform: 'scale(' + s + ')' } : null, parent);
    const wrap = { fill: D.light, stroke: D.deep, 'stroke-width': 1.5, 'stroke-linejoin': 'round' };
    mk('path', Object.assign({ d: 'M-15,-3.5 L-27,-11 Q-30.5,0 -27,11 L-15,3.5 Z' }, wrap), g);
    mk('path', Object.assign({ d: 'M15,-3.5 L27,-11 Q30.5,0 27,11 L15,3.5 Z' }, wrap), g);
    mk('path', { d: 'M-24,-6 L-19,0 L-24,6 M24,-6 L19,0 L24,6', stroke: D.deep, 'stroke-width': 1, fill: 'none', opacity: 0.5 }, g);
    mk('rect', { x: -17, y: -12, width: 34, height: 24, rx: 12, fill: 'url(#gd-' + type + ')', stroke: D.deep, 'stroke-width': 1.8 }, g);
    if (!D.good) mk('rect', { x: -20.5, y: -15.5, width: 41, height: 31, rx: 15.5, fill: 'none', stroke: D.deep, 'stroke-width': 1.4, 'stroke-dasharray': '2.5 2.5', opacity: 0.8 }, g);
    mk('rect', { x: -11, y: -9.5, width: 22, height: 5.5, rx: 2.75, fill: '#fff', opacity: 0.55 }, g);
    txt(g, 0, 5.5, D.ch, { 'text-anchor': 'middle', 'font-size': 15, 'font-weight': 900, fill: '#fff', stroke: D.deep, 'stroke-width': 3, 'paint-order': 'stroke' });
    return g;
  }

  // ================= fx pools =================
  const P_SHAPES = {
    dot: 'M-3,0 A3,3 0 1,0 3,0 A3,3 0 1,0 -3,0 Z',
    sprinkle: 'M-5,-1.6 H5 A1.6,1.6 0 0 1 5,1.6 H-5 A1.6,1.6 0 0 1 -5,-1.6 Z',
    star: 'M0,-5 L1.4,-1.4 L5,0 L1.4,1.4 L0,5 L-1.4,1.4 L-5,0 L-1.4,-1.4 Z',
    shard: 'M-4,-3 L4,-2 L1,4 Z',
    heart: 'M0,3.4 C-5,-0.6 -3.6,-5 0,-2.6 C3.6,-5 5,-0.6 0,3.4 Z',
  };
  function makePool(parent, n) {
    const list = [];
    for (let i = 0; i < n; i++) list.push({ e: mk('path', { d: P_SHAPES.dot, style: 'display:none' }, parent), on: false, shape: 'dot', color: '' });
    let idx = 0;
    return {
      spawn(x, y, vx, vy, color, shape, life, s, g, drag) {
        let p = null;
        for (let k = 0; k < n; k++) { const q = list[(idx + k) % n]; if (!q.on) { p = q; idx = (idx + k + 1) % n; break; } }
        if (!p) { p = list[idx]; idx = (idx + 1) % n; }
        p.on = true; p.x = x; p.y = y; p.vx = vx; p.vy = vy; p.rot = rand(0, 360); p.vr = rand(-540, 540);
        p.life = 0; p.max = life; p.s = s; p.g = g === undefined ? 900 : g; p.drag = drag === undefined ? 0.9 : drag;
        if (p.shape !== shape) { p.shape = shape; p.e.setAttribute('d', P_SHAPES[shape]); }
        if (p.color !== color) { p.color = color; p.e.setAttribute('fill', color); }
        p.e.style.display = '';
        return p;
      },
      update(dt) {
        for (const p of list) {
          if (!p.on) continue;
          p.life += dt;
          if (p.life >= p.max) { p.on = false; p.e.style.display = 'none'; continue; }
          p.vy += p.g * dt;
          const dr = 1 - p.drag * dt;
          p.vx *= dr; p.vy *= dr;
          p.x += p.vx * dt; p.y += p.vy * dt; p.rot += p.vr * dt;
          const k = p.life / p.max;
          const sc = p.s * (k > 0.65 ? 1 - (k - 0.65) / 0.35 : 1);
          p.e.setAttribute('transform', 'translate(' + r1(p.x) + ',' + r1(p.y) + ') rotate(' + (p.rot | 0) + ') scale(' + r3(sc) + ')');
        }
      },
      clear() { for (const p of list) if (p.on) { p.on = false; p.e.style.display = 'none'; } },
    };
  }
  const rings = [];
  for (let i = 0; i < 18; i++) rings.push({ e: mk('circle', { r: 1, fill: 'none', style: 'display:none' }, L_fx), on: false });
  const fx = makePool(L_fx, 280);
  const pops = [];
  for (let i = 0; i < 22; i++) pops.push({ e: mk('text', { 'text-anchor': 'middle', 'font-weight': 900, stroke: '#fff', 'stroke-width': 4, 'paint-order': 'stroke', 'stroke-linejoin': 'round', style: 'display:none' }, L_pops), on: false });
  let popIdx = 0;

  function ring(x, y, color, ra, rb, dur, w) {
    let rg = rings.find((q) => !q.on);
    if (!rg) rg = rings[0];
    rg.on = true; rg.x = x; rg.y = y; rg.ra = ra; rg.rb = rb; rg.t = 0; rg.dur = dur; rg.w = w;
    rg.e.setAttribute('stroke', color);
    rg.e.style.display = '';
  }
  function updateRings(dt) {
    for (const rg of rings) {
      if (!rg.on) continue;
      rg.t += dt;
      const k = rg.t / rg.dur;
      if (k >= 1) { rg.on = false; rg.e.style.display = 'none'; continue; }
      const e = 1 - Math.pow(1 - k, 2);
      rg.e.setAttribute('cx', r1(rg.x)); rg.e.setAttribute('cy', r1(rg.y));
      rg.e.setAttribute('r', r1(lerp(rg.ra, rg.rb, e)));
      rg.e.setAttribute('stroke-width', r1(rg.w * (1 - k) + 0.5));
      rg.e.setAttribute('opacity', r3(1 - k));
    }
  }
  function popup(x, y, str, color, size, life) {
    const p = pops[popIdx]; popIdx = (popIdx + 1) % pops.length;
    p.on = true; p.x = x; p.y = y; p.t = 0; p.life = life || 0.9;
    p.e.textContent = str;
    p.e.setAttribute('fill', color);
    p.e.setAttribute('font-size', size || 18);
    p.e.style.display = '';
  }
  function updatePops(dt) {
    for (const p of pops) {
      if (!p.on) continue;
      p.t += dt;
      const k = p.t / p.life;
      if (k >= 1) { p.on = false; p.e.style.display = 'none'; continue; }
      const s = k < 0.15 ? 0.6 + (k / 0.15) * 0.55 : 1.15 - Math.min(0.15, (k - 0.15));
      p.e.setAttribute('transform', 'translate(' + r1(p.x) + ',' + r1(p.y - 42 * (1 - Math.pow(1 - k, 2))) + ') scale(' + r3(s) + ')');
      p.e.setAttribute('opacity', r3(k > 0.7 ? 1 - (k - 0.7) / 0.3 : 1));
    }
  }
  function crumbs(k, n, power) {
    const c = COLORS[k.color];
    const cols = [c.base, c.light, c.deep, '#ffffff', c.base];
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2), sp = rand(70, 300) * power;
      fx.spawn(k.x + rand(-13, 13), k.y + rand(-7, 7), Math.cos(a) * sp, Math.sin(a) * sp - 150 * power, pick(cols), pick(['dot', 'sprinkle', 'sprinkle', 'shard', 'star']), rand(0.55, 1.05), rand(0.7, 1.35));
    }
  }
  function sparks(x, y, color, n) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2), sp = rand(60, 200);
      fx.spawn(x, y, Math.cos(a) * sp, Math.sin(a) * sp, i % 2 ? '#ffffff' : color, 'star', rand(0.25, 0.5), rand(0.5, 0.9), 200);
    }
  }
  function burst(x, y, n, pool) {
    const cols = ['#ff8fbd', '#ffd86e', '#6fe0b9', '#b9a0ff', '#88cefb', '#ffffff', '#ff7088'];
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2), sp = rand(120, 420);
      (pool || fx).spawn(x, y, Math.cos(a) * sp, Math.sin(a) * sp, pick(cols), pick(['star', 'dot', 'sprinkle', 'heart']), rand(0.6, 1.2), rand(0.9, 1.6), 380, 1.6);
    }
  }

  // ================= paddle & ball visuals =================
  const PV = {};
  function buildPaddle() {
    PV.shadow = mk('path', { fill: '#6a1f4a', opacity: 0.16 }, L_paddle);
    PV.body = mk('path', { fill: 'url(#pat-paddle)', stroke: '#d9477f', 'stroke-width': 2 }, L_paddle);
    PV.gloss = mk('path', { fill: 'none', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linecap': 'round', opacity: 0.75 }, L_paddle);
    PV.honey = mk('path', { fill: '#ffcf4d', opacity: 0.82, stroke: '#e0a020', 'stroke-width': 1.2, style: 'display:none' }, L_paddle);
    PV.caps = [capArt(), capArt()];
  }
  function capArt() {
    const g = mk('g', null, L_paddle);
    const laser = mk('g', { style: 'display:none' }, g);
    mk('rect', { x: -4.5, y: -24, width: 9, height: 14, rx: 3.5, fill: '#8ff0d4', stroke: '#27a883', 'stroke-width': 1.6 }, laser);
    mk('circle', { cx: 0, cy: -23, r: 3.2, fill: '#fff' }, laser);
    const inner = mk('g', null, g);
    mk('circle', { r: 12.5, fill: 'url(#g-cap)', stroke: '#d9477f', 'stroke-width': 2 }, inner);
    mk('path', { d: SPIRAL, fill: 'none', stroke: '#fff', 'stroke-width': 2.2, 'stroke-linecap': 'round' }, inner);
    mk('ellipse', { cx: -4, cy: -6, rx: 4, ry: 2.3, fill: '#fff', opacity: 0.75 }, g);
    return { g: g, inner: inner, laser: laser };
  }
  function paddlePath(hw, bend, u, hh, ox, oy) {
    const bx = u * hw * 0.8 + ox, by = 2 * bend;
    const L = -hw + hh + ox, Rr = hw - hh + ox;
    return 'M' + r1(L) + ',' + (-hh + oy) + ' Q' + r1(bx) + ',' + r1(-hh + by + oy) + ' ' + r1(Rr) + ',' + (-hh + oy) +
      ' A' + hh + ',' + hh + ' 0 0 1 ' + r1(Rr) + ',' + (hh + oy) + ' Q' + r1(bx) + ',' + r1(hh + by + oy) + ' ' + r1(L) + ',' + (hh + oy) +
      ' A' + hh + ',' + hh + ' 0 0 1 ' + r1(L) + ',' + (-hh + oy) + ' Z';
  }
  function honeyPath(hw, bend, u) {
    const bx = u * hw * 0.8, by = 2 * bend;
    let d = 'M' + r1(-hw + 4) + ',-2 Q' + r1(bx) + ',' + r1(-11 + by) + ' ' + r1(hw - 4) + ',-2';
    const n = Math.max(3, Math.round(hw / 14));
    for (let i = 0; i <= n; i++) {
      const x = hw - 4 - ((2 * hw - 8) * i) / n;
      const yb = 2 + bend * (1 - Math.pow((x - bx) / hw, 2)) * 0.9;
      d += ' Q' + r1(x + 5) + ',' + r1(yb + (i % 2 ? 15 : 4)) + ' ' + r1(x) + ',' + r1(yb);
    }
    return d + ' Z';
  }
  function renderPaddle() {
    const hw = pad.w / 2, bodyHw = hw - 9;
    const key = r1(pad.w) + '|' + r1(pad.bend) + '|' + r3(pad.u) + '|' + (eff.sticky > 0 ? 1 : 0);
    if (key !== PV.key) {
      PV.key = key;
      PV.body.setAttribute('d', paddlePath(bodyHw, pad.bend, pad.u, 8, 0, 0));
      PV.shadow.setAttribute('d', paddlePath(bodyHw, pad.bend, pad.u, 8, 3, 7));
      PV.gloss.setAttribute('d', 'M' + r1(-bodyHw + 8) + ',-3.4 Q' + r1(pad.u * bodyHw * 0.8) + ',' + r1(-3.4 + 2 * pad.bend) + ' ' + r1(bodyHw - 8) + ',-3.4');
      if (eff.sticky > 0) PV.honey.setAttribute('d', honeyPath(bodyHw, pad.bend, pad.u));
    }
    show(PV.honey, eff.sticky > 0);
    L_paddle.setAttribute('transform', 'translate(' + r1(pad.x) + ',' + PADDLE_Y + ')');
    const las = eff.laser > 0;
    for (let i = 0; i < 2; i++) {
      const c = PV.caps[i], s = i ? 1 : -1;
      c.g.setAttribute('transform', 'translate(' + r1(s * (hw - 10)) + ',' + r1(pad.bend * 0.25) + ')');
      c.inner.setAttribute('transform', 'rotate(' + ((pad.rot * s) | 0) + ')');
      if (c.las !== las) { c.las = las; show(c.laser, las); }
    }
  }
  const ballVis = [];
  function buildBallVisuals() {
    for (let i = 0; i < MAX_BALLS; i++) {
      const trail = [];
      for (let j = 0; j < TRAIL_N; j++) trail.push(mk('line', { 'stroke-linecap': 'round', style: 'display:none' }, L_trails));
      const g = mk('g', { style: 'display:none' }, L_balls);
      const glow = mk('circle', { r: 20, fill: 'url(#g-fireglow)', style: 'display:none' }, g);
      mk('ellipse', { cx: 2, cy: 7, rx: 9, ry: 3, fill: '#6a1f4a', opacity: 0.12 }, g);
      const inner = mk('g', null, g);
      const body = mk('path', { d: BEAN, fill: 'url(#g-bean)', stroke: '#c23a78', 'stroke-width': 1.5 }, inner);
      mk('path', { d: BEAN_HL, fill: '#fff', opacity: 0.88 }, inner);
      mk('circle', { cx: 6, cy: 3, r: 1.3, fill: '#fff', opacity: 0.6 }, inner);
      ballVis.push({ g: g, inner: inner, body: body, glow: glow, trail: trail, used: false, fire: false });
    }
  }

  // ================= game state =================
  let state = 'boot', mode = 'demo', diffKey = save.diff;
  let levelIdx = 0, demoLevel = 0;
  let score = 0, shownScore = 0, bestAtStart = 0, lives = 3;
  let bricks = [], grid = [], balls = [], drops = [], pendingPops = [], moveGroups = [];
  let breakableLeft = 0, breakableTotal = 1;
  let combo = 0, maxCombo = 0, lastTier = 1;
  let levelTime = 0, levelPar = 150, levelScore = 0, levelClock = 0;
  let levelStartScore = 0, levelStartLives = 3;
  let T = 0, shakeT = 0, shakeA = 0, introT = -1;
  let clearing = false, clearT = 0, overT = -1, serveT = 0, laserCD = 0, speedRamp = 0;
  let helpFrom = 'title', menu = null, menuSel = 0, screenT = 0;
  let demoAim = 0, autoPlay = false;
  let toastT = -1, comboT = -1, heartT = 0;
  const eff = { expand: 0, shrink: 0, slow: 0, fast: 0, laser: 0, sticky: 0, fire: 0 };
  const pad = { x: 640, w: 114, tw: 114, vx: 0, vk: 0, bend: 0, bendV: 0, u: 0, rot: 0 };
  const keys = { left: false, right: false, fire: false };
  let mouseHeld = false;
  let inputMode = 'key', mouseX = 640;
  const lasers = [];
  for (let i = 0; i < 20; i++) {
    const g = mk('g', { style: 'display:none' }, L_lasers);
    mk('rect', { x: -4.5, y: -13, width: 9, height: 26, rx: 4.5, fill: '#ff8fbd', opacity: 0.35 }, g);
    mk('rect', { x: -2.5, y: -11, width: 5, height: 22, rx: 2.5, fill: '#ffffff' }, g);
    mk('rect', { x: -1.2, y: -9, width: 2.4, height: 18, rx: 1.2, fill: '#ff4f93' }, g);
    lasers.push({ g: g, on: false, x: 0, y: 0 });
  }

  function curDiff() { return DIFF[mode === 'demo' ? 'normal' : diffKey]; }
  function baseSpeed() {
    let s = curDiff().speed * (mode === 'demo' ? 0.92 : 1) * (1 + 0.03 * (mode === 'demo' ? 0 : levelIdx)) * (1 + 0.12 * speedRamp);
    if (eff.slow > 0) s *= 0.7;
    if (eff.fast > 0) s *= 1.3;
    return s;
  }
  const comboMult = () => Math.min(8, 1 + Math.floor(combo / 4));
  function shake(t, a) { shakeT = Math.max(shakeT, t); shakeA = Math.max(shakeA, a); }

  // ================= level loading =================
  function loadLevel(idx) {
    for (const k of bricks) if (k.g && k.g.parentNode) k.g.remove();
    bricks = []; pendingPops = []; grid = [];
    const L = LEVELS[idx];
    const width = Math.max.apply(null, L.rows.map((r) => r.length));
    const off = Math.floor((COLS - width) / 2);
    L.rows.forEach((row, r) => {
      grid[r] = [];
      for (let c = 0; c < row.length; c++) {
        const cell = parseCell(row[c]);
        if (!cell) continue;
        const col = c + off;
        const k = Object.assign(cell, { row: r, col: col, bx: GX0 + col * CW, x: GX0 + col * CW, y: GY0 + r * CH, alive: true, maxHp: cell.hp, wob: 9, wobV: true, wobA: 1, mv: -1, popping: false });
        grid[r][col] = k;
        bricks.push(k);
      }
    });
    moveGroups = (L.moves || []).map((m) => Object.assign({}, m, { off: 0, v: 0 }));
    moveGroups.forEach((g, gi) => {
      let minX = 1e9, maxX = -1e9;
      for (const k of bricks) if (g.rows.indexOf(k.row) >= 0) { k.mv = gi; minX = Math.min(minX, k.bx - BW / 2); maxX = Math.max(maxX, k.bx + BW / 2); }
      g.amp = Math.max(0, Math.min(g.amp, minX - FX0 - 6, FX1 - 6 - maxX));
    });
    for (const k of bricks) buildBrick(k);
    breakableTotal = breakableLeft = bricks.filter((k) => k.type !== 'choco').length;
    levelClock = 0;
  }
  function brickAt(r, c) { const row = grid[r]; return row ? row[c] : null; }

  // ================= balls =================
  function newBall(x, y, vx, vy) {
    const vis = ballVis.find((v) => !v.used);
    if (!vis) return null;
    vis.used = true; show(vis.g, true);
    const b = { x: x, y: y, vx: vx || 0, vy: vy || 0, stuck: false, serve: false, off: 0, stuckT: 0, hist: [], vis: vis, sq: 0, dead: false, idle: 0 };
    balls.push(b);
    return b;
  }
  function freeBall(b) {
    b.vis.used = false; show(b.vis.g, false);
    for (const l of b.vis.trail) { l.__on = false; l.style.display = 'none'; }
  }
  function clearBalls() { for (const b of balls) freeBall(b); balls = []; }
  function resetServe() {
    clearBalls();
    const b = newBall(pad.x, PADDLE_TOP - R);
    b.stuck = true; b.serve = true; b.off = rand(-0.2, 0.2) * pad.w;
    serveT = 0;
  }
  function releaseBalls() {
    let any = false;
    const sp = baseSpeed();
    for (const b of balls) {
      if (!b.stuck || b.dead) continue;
      any = true;
      const u = clamp(b.off / (pad.w / 2), -1, 1);
      let ang = u * MAX_ANGLE * 0.9;
      if (Math.abs(ang) < 0.14) ang = (ang < 0 ? -1 : 1) * 0.14;
      b.vx = Math.sin(ang) * sp; b.vy = -Math.cos(ang) * sp;
      b.stuck = false; b.serve = false; b.y = PADDLE_TOP - R - 1; b.hist.length = 0; b.idle = 0;
    }
    if (any && mode === 'game') Snd.sfx.launch();
    return any;
  }
  function fixAngle(b) {
    const sp = Math.hypot(b.vx, b.vy) || 1, minVy = sp * 0.26;
    if (Math.abs(b.vy) < minVy) {
      b.vy = (b.vy < 0 ? -1 : 1) * minVy;
      b.vx = (b.vx < 0 ? -1 : 1) * Math.sqrt(Math.max(0, sp * sp - minVy * minVy));
    }
  }
  function updateBall(b, dt, sp) {
    if (b.dead) return;
    if (b.stuck) {
      b.off = clamp(b.off, -pad.w / 2 + 4, pad.w / 2 - 4);
      b.x = clamp(pad.x + b.off, FX0 + R, FX1 - R);
      b.y = PADDLE_TOP - R + pad.bend * 0.6;
      if (!b.serve) b.stuckT += dt;
      return;
    }
    const cur = Math.hypot(b.vx, b.vy) || 1;
    const ns = lerp(cur, sp, Math.min(1, dt * 2.5));
    b.vx *= ns / cur; b.vy *= ns / cur;
    b.idle += dt;
    if (b.idle > 9) {
      const a = rand(0.25, 0.45) * (Math.random() < 0.5 ? -1 : 1), c = Math.cos(a), s = Math.sin(a);
      const vx = b.vx * c - b.vy * s; b.vy = b.vx * s + b.vy * c; b.vx = vx;
      fixAngle(b); b.idle = 0;
    }
    const steps = Math.max(1, Math.ceil((ns * dt) / 4));
    const h = dt / steps;
    for (let s = 0; s < steps; s++) {
      const py = b.y;
      b.x += b.vx * h; b.y += b.vy * h;
      if (b.x < FX0 + R) { b.x = FX0 + R; b.vx = Math.abs(b.vx); wallBump(); }
      else if (b.x > FX1 - R) { b.x = FX1 - R; b.vx = -Math.abs(b.vx); wallBump(); }
      if (b.y < FY0 + R) { b.y = FY0 + R; b.vy = Math.abs(b.vy); wallBump(); }
      if (b.vy > 0 && py + R <= PADDLE_TOP + 7 && b.y + R >= PADDLE_TOP) {
        const hw = pad.w / 2;
        if (b.x >= pad.x - hw - R * 0.7 && b.x <= pad.x + hw + R * 0.7) {
          paddleHit(b);
          if (b.stuck) return;
          continue;
        }
      }
      collideBricks(b);
      if (b.y - R > 735) { b.dead = true; return; }
    }
  }
  function wallBump() { if (mode === 'game') Snd.sfx.wall(); }
  function paddleHit(b) {
    const hw = pad.w / 2;
    const u = clamp((b.x - pad.x) / hw, -1, 1);
    const ang = u * MAX_ANGLE;
    const sp = Math.hypot(b.vx, b.vy);
    b.vx = Math.sin(ang) * sp; b.vy = -Math.cos(ang) * sp;
    b.y = PADDLE_TOP - R;
    b.sq = 1; b.idle = 0;
    pad.bendV += 90 + sp * 0.06; pad.u = u * 0.9;
    combo = 0; lastTier = 1;
    for (let i = 0; i < 4; i++) fx.spawn(b.x + rand(-6, 6), PADDLE_TOP - 2, rand(-120, 120), rand(-220, -80), pick(['#ffffff', '#ffd86e', '#ff8fbd', '#8ee6c3']), 'star', rand(0.25, 0.45), rand(0.5, 0.8), 500);
    if (eff.sticky > 0) {
      b.stuck = true; b.off = b.x - pad.x; b.stuckT = 0; b.vx = 0; b.vy = 0; b.hist.length = 0;
      if (mode === 'game') Snd.sfx.stick();
    } else if (mode === 'game') Snd.sfx.paddle();
    if (mode === 'demo' || autoPlay) demoAim = rand(-0.8, 0.8);
  }
  function collideBricks(b) {
    const fire = eff.fire > 0;
    const hw = BW / 2, hh = BH / 2;
    for (let i = 0; i < bricks.length; i++) {
      const k = bricks[i];
      if (!k.alive) continue;
      const dx = b.x - k.x, dy = b.y - k.y;
      if (dx > hw + R || dx < -hw - R || dy > hh + R || dy < -hh - R) continue;
      const cx = clamp(dx, -hw, hw), cy = clamp(dy, -hh, hh);
      const ex = dx - cx, ey = dy - cy, d2 = ex * ex + ey * ey;
      if (d2 >= R * R) continue;
      if (fire && k.type !== 'choco') { hitBrick(k, b, 0, 1, true); continue; }
      let nx, ny;
      if (d2 > 1e-6) {
        const d = Math.sqrt(d2);
        nx = ex / d; ny = ey / d;
        if (Math.abs(nx) > 0.05 && Math.abs(ny) > 0.05) {
          const hn = brickAt(k.row, k.col + (nx > 0 ? 1 : -1));
          const vn = brickAt(k.row + (ny > 0 ? 1 : -1), k.col);
          const hA = !!(hn && hn.alive && hn.mv === k.mv), vA = !!(vn && vn.alive && vn.mv === k.mv && k.mv < 0);
          if (hA && !vA) { nx = 0; ny = ny > 0 ? 1 : -1; }
          else if (vA && !hA) { ny = 0; nx = nx > 0 ? 1 : -1; }
        }
      } else {
        const px = hw + R - Math.abs(dx), pyy = hh + R - Math.abs(dy);
        if (px < pyy) { nx = dx < 0 ? -1 : 1; ny = 0; } else { nx = 0; ny = dy < 0 ? -1 : 1; }
      }
      if (ny === 0) b.x = k.x + nx * (hw + R + 0.05);
      else if (nx === 0) b.y = k.y + ny * (hh + R + 0.05);
      else { b.x = k.x + cx + nx * (R + 0.05); b.y = k.y + cy + ny * (R + 0.05); }
      const vn2 = b.vx * nx + b.vy * ny;
      if (vn2 < 0) { b.vx -= 2 * vn2 * nx; b.vy -= 2 * vn2 * ny; }
      if (k.mv >= 0 && nx !== 0) {
        const gv = moveGroups[k.mv].v;
        if (gv * nx > 0 && b.vx * nx < Math.abs(gv) + 40) b.vx = nx * (Math.abs(gv) + 60);
      }
      fixAngle(b);
      hitBrick(k, b, nx, ny, false);
      return true;
    }
    return false;
  }
  function wobble(k, vertical, amp) {
    if (k.wob < 0.8 && k.wobA > amp) return;
    k.wob = 0; k.wobV = vertical; k.wobA = amp;
  }
  function hitBrick(k, b, nx, ny, fire) {
    wobble(k, Math.abs(ny) >= Math.abs(nx), 1);
    if (k.type === 'choco') {
      if (mode === 'game') Snd.sfx.choco();
      sparks(b ? b.x - nx * R : k.x, b ? b.y - ny * R : k.y + BH / 2, '#ffd9b8', 4);
      return;
    }
    if (b) b.idle = 0;
    k.hp -= fire ? k.hp : 1;
    if (k.hp <= 0) destroyBrick(k);
    else {
      updateCracks(k);
      if (mode === 'game') Snd.sfx.crack();
      addScore(20, k.x, k.y - 6, COLORS[k.color].deep, false);
      crumbs(k, 4, 0.55);
    }
  }
  function destroyBrick(k) {
    if (!k.alive) return;
    k.alive = false;
    if (k.g.parentNode) k.g.remove();
    breakableLeft--;
    combo++;
    if (combo > maxCombo) maxCombo = combo;
    const mult = comboMult();
    const base = k.type === 'hard' ? (k.maxHp >= 3 ? 180 : 120) : k.type === 'pop' ? 100 : k.type === 'gift' ? 80 : 50;
    addScore(base * mult, k.x, k.y, COLORS[k.color].deep, true);
    crumbs(k, 12, 1);
    ring(k.x, k.y, COLORS[k.color].base, 8, 34, 0.35, 3);
    for (const o of bricks) if (o.alive && Math.abs(o.x - k.x) < CW * 1.6 && Math.abs(o.y - k.y) < CH * 1.6) wobble(o, Math.abs(o.y - k.y) > Math.abs(o.x - k.x) * 0.75, 0.45);
    if (mode === 'game') Snd.sfx.brick(combo);
    if (k.type === 'pop') explode(k);
    if (k.type === 'gift') spawnDrop(k.x, k.y);
    else if (Math.random() < 0.05) spawnDrop(k.x, k.y);
    if (mult > lastTier) { lastTier = mult; comboPopup(mult); }
    speedRamp = 1 - breakableLeft / breakableTotal;
    if (breakableLeft <= 0) levelCleared();
  }
  function explode(k) {
    shake(0.3, 6);
    if (mode === 'game') Snd.sfx.boom();
    ring(k.x, k.y, '#ffe95c', 10, 72, 0.45, 6);
    ring(k.x, k.y, '#c78bff', 6, 54, 0.35, 4);
    burst(k.x, k.y, 20);
    for (const o of bricks) {
      if (!o.alive || o === k || o.type === 'choco' || o.popping) continue;
      if (Math.abs(o.x - k.x) <= CW * 1.15 && Math.abs(o.y - k.y) <= CH * 1.15) {
        if (o.type === 'pop') { o.popping = true; pendingPops.push({ k: o, t: 0.12 }); }
        else destroyBrick(o);
      }
    }
  }
  function addScore(p, x, y, color, big) {
    if (mode === 'game') { score += p; levelScore += p; }
    let active = 0;
    for (const q of pops) if (q.on) active++;
    if (active > 9 && p < 400) return;
    popup(x, y, '+' + fmt(p), color, big ? (p >= 400 ? 18 : 15) : 13, big ? 0.8 : 0.55);
  }
  function comboPopup(m) {
    if (mode !== 'game') return;
    setText($('combo-pop-t'), F(S.comboPop, { n: m }));
    comboT = 0; show('combo-pop', true);
    if (mode === 'game') { Snd.sfx.combo(m); if (m >= 2) mascotMood('happy', 1.1); }
  }

  // ================= drops / lasers =================
  function pickDrop() {
    const bad = mode === 'demo' ? 0.12 : DIFF[diffKey].bad;
    if (Math.random() < bad) return pick(BAD_KEYS);
    let total = 0;
    for (const k of GOOD_KEYS) total += DROPS[k].w;
    let r = Math.random() * total;
    for (const k of GOOD_KEYS) { r -= DROPS[k].w; if (r <= 0) return k; }
    return 'expand';
  }
  function spawnDrop(x, y, type) {
    type = type || pickDrop();
    const g = mk('g', null, L_drops);
    dropArt(g, type, 1);
    drops.push({ x: x, y: y, vy: 30, type: type, g: g, t: rand(0, 6) });
  }
  function clearDrops() { for (const d of drops) d.g.remove(); drops = []; }
  function updateDrops(dt) {
    for (let i = drops.length - 1; i >= 0; i--) {
      const d = drops[i];
      d.t += dt; d.vy = Math.min(d.vy + 320 * dt, 165); d.y += d.vy * dt;
      if (d.y + 12 >= PADDLE_TOP - 4 && d.y - 12 <= PADDLE_Y + 10 && Math.abs(d.x - pad.x) <= pad.w / 2 + 24 && overT < 0) {
        d.g.remove(); drops.splice(i, 1); applyDrop(d.type);
        continue;
      }
      if (d.y > 760) { d.g.remove(); drops.splice(i, 1); continue; }
      d.g.setAttribute('transform', 'translate(' + r1(d.x) + ',' + r1(d.y) + ') rotate(' + r1(Math.sin(d.t * 5) * 9) + ')');
    }
  }
  function applyDrop(type) {
    const D = DROPS[type];
    switch (type) {
      case 'expand': eff.expand = D.dur; eff.shrink = 0; break;
      case 'shrink': eff.shrink = D.dur; eff.expand = 0; break;
      case 'slow': eff.slow = D.dur; eff.fast = 0; break;
      case 'fast': eff.fast = D.dur; eff.slow = 0; break;
      case 'laser': eff.laser = D.dur; break;
      case 'sticky': eff.sticky = D.dur; break;
      case 'fire': eff.fire = D.dur; break;
      case 'multi': multiBall(); break;
    }
    ring(pad.x, PADDLE_Y, D.base, 16, 96, 0.45, 5);
    for (let i = 0; i < 10; i++) fx.spawn(pad.x + rand(-pad.w / 2, pad.w / 2), PADDLE_Y - 6, rand(-80, 80), rand(-300, -120), i % 2 ? '#ffffff' : D.base, D.good ? 'star' : 'dot', rand(0.4, 0.8), rand(0.7, 1.2), 400);
    if (mode === 'game') {
      score += D.good ? 100 : 30;
      popup(pad.x, PADDLE_Y - 34, D.name, D.deep, 22, 1.1);
      if (D.good) { Snd.sfx.good(); mascotMood('happy', 0.9); } else { Snd.sfx.bad(); mascotMood('sad', 1.0); }
      if (type === 'laser') toast(S.laserTip);
      else if (type === 'sticky') toast(S.stickyTip);
    }
  }
  function multiBall() {
    const src = balls.filter((b) => !b.dead);
    const sp = baseSpeed();
    for (const b of src) {
      for (const da of [-0.45, 0.45]) {
        if (balls.length >= MAX_BALLS) break;
        let vx = b.vx, vy = b.vy;
        if (b.stuck || Math.hypot(vx, vy) < 1) { vx = 0; vy = -sp; }
        const c = Math.cos(da), s = Math.sin(da);
        const nb = newBall(b.x, b.stuck ? b.y - 4 : b.y, vx * c - vy * s, vx * s + vy * c);
        if (!nb) break;
        if (b.stuck && nb.vy > 0) nb.vy = -nb.vy;
        fixAngle(nb);
      }
    }
  }
  function fireLaser() {
    if (eff.laser <= 0 || laserCD > 0) return false;
    laserCD = 0.26;
    const hw = pad.w / 2 - 10;
    for (const s of [-1, 1]) {
      const l = lasers.find((q) => !q.on);
      if (!l) break;
      l.on = true; l.x = pad.x + s * hw; l.y = PADDLE_TOP - 20;
      show(l.g, true);
      l.g.setAttribute('transform', 'translate(' + r1(l.x) + ',' + r1(l.y) + ')');
    }
    if (mode === 'game') Snd.sfx.laser();
    return true;
  }
  function clearLasers() { for (const l of lasers) if (l.on) { l.on = false; show(l.g, false); } }
  function updateLasers(dt) {
    for (const l of lasers) {
      if (!l.on) continue;
      l.y -= 880 * dt;
      let hit = null;
      for (const k of bricks) {
        if (!k.alive) continue;
        if (Math.abs(l.x - k.x) <= BW / 2 + 2 && l.y - 11 <= k.y + BH / 2 && l.y + 11 >= k.y - BH / 2 && (!hit || k.y > hit.y)) hit = k;
      }
      if (hit) { hitBrick(hit, null, 0, 1, false); sparks(l.x, hit.y + BH / 2, '#ff8fbd', 5); l.on = false; show(l.g, false); continue; }
      if (l.y < FY0 + 6) { sparks(l.x, FY0 + 6, '#ffffff', 3); l.on = false; show(l.g, false); continue; }
      l.g.setAttribute('transform', 'translate(' + r1(l.x) + ',' + r1(l.y) + ')');
    }
  }

  // ================= world update =================
  function aiTarget() {
    let best = null, bestT = 1e9;
    for (const b of balls) {
      if (b.stuck || b.dead || b.vy <= 0) continue;
      const t = (PADDLE_TOP - R - b.y) / b.vy;
      if (t >= -0.05 && t < bestT) { bestT = t; best = b; }
    }
    if (!best) {
      let d = null;
      for (const q of drops) if (DROPS[q.type].good && q.y < PADDLE_Y && (!d || q.y > d.y)) d = q;
      if (d) return d.x;
      const b0 = balls.find((b) => !b.dead);
      if (!b0) return 640;
      return b0.stuck ? 640 + Math.sin(T * 1.3) * 90 : b0.x;
    }
    let x = best.x + best.vx * Math.max(0, bestT);
    const L = FX0 + R, span = FX1 - R - L;
    let m = (x - L) % (2 * span);
    if (m < 0) m += 2 * span;
    x = m <= span ? L + m : L + 2 * span - m;
    return x - demoAim * pad.w * 0.42;
  }
  function updatePaddle(dt) {
    const d = curDiff();
    pad.tw = d.paddle * (eff.expand > 0 ? 1.45 : eff.shrink > 0 ? 0.62 : 1);
    pad.w = lerp(pad.w, pad.tw, Math.min(1, dt * 9));
    const hw = pad.w / 2;
    let x = pad.x;
    const live = !clearing && overT < 0;
    if ((mode === 'demo' || autoPlay) && live) {
      const maxV = 1050 * dt;
      x += clamp(aiTarget() - x, -maxV, maxV);
    } else if (state === 'play' && live) {
      const dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
      if (dir !== 0) {
        inputMode = 'key';
        if (Math.sign(pad.vk) !== dir) pad.vk = dir * 320;
        pad.vk = clamp(pad.vk + dir * 9000 * dt, -900, 900);
        x += pad.vk * dt;
      } else {
        pad.vk = 0;
        if (inputMode === 'mouse') x = lerp(x, mouseX, Math.min(1, dt * 30));
      }
    }
    x = clamp(x, FX0 + hw, FX1 - hw);
    pad.vx = dt > 0 ? (x - pad.x) / dt : 0;
    pad.x = x;
    pad.bendV += (-320 * pad.bend - 12 * pad.bendV) * dt;
    pad.bend += pad.bendV * dt;
    pad.rot += pad.vx * dt * 2.2;
  }
  function updateWorld(dt) {
    levelClock += dt;
    updatePaddle(dt);
    for (const g of moveGroups) {
      const o = g.amp * Math.sin(levelClock * g.speed + g.phase);
      g.v = dt > 0 ? (o - g.off) / dt : 0;
      g.off = o;
    }
    if (moveGroups.length) for (const k of bricks) if (k.alive && k.mv >= 0) k.x = k.bx + moveGroups[k.mv].off;
    for (const key in eff) if (eff[key] > 0) eff[key] = Math.max(0, eff[key] - dt);
    laserCD = Math.max(0, laserCD - dt);
    for (let i = pendingPops.length - 1; i >= 0; i--) {
      const p = pendingPops[i];
      p.t -= dt;
      if (p.t <= 0) { pendingPops.splice(i, 1); if (p.k.alive) destroyBrick(p.k); }
    }
    const sp = baseSpeed();
    for (const b of balls) updateBall(b, dt, sp);
    for (let i = balls.length - 1; i >= 0; i--) if (balls[i].dead) { freeBall(balls[i]); balls.splice(i, 1); }
    if (!clearing && overT < 0 && balls.length === 0) ballsLost();
    updateDrops(dt);
    updateLasers(dt);
    if (eff.fire > 0) for (const b of balls) if (!b.stuck && Math.random() < 0.7) fx.spawn(b.x + rand(-4, 4), b.y + rand(-4, 4), rand(-30, 30), rand(-90, -30), pick(['#ffcf3d', '#ff7a45', '#ffe9a8']), 'dot', rand(0.25, 0.45), rand(0.5, 0.9), -60, 1);
    if (!clearing && overT < 0 && !balls.some((b) => b.serve)) levelTime += dt;
    serveT += dt;
    if (mode === 'demo' || autoPlay) {
      for (const b of balls) if (b.stuck && (b.serve ? serveT > 0.9 : b.stuckT > 0.35)) { releaseBalls(); break; }
      if (eff.laser > 0 && Math.random() < 0.12) fireLaser();
    } else {
      for (const b of balls) if (b.stuck && !b.serve && b.stuckT > 3) { releaseBalls(); break; }
      if ((keys.fire || mouseHeld) && eff.laser > 0 && state === 'play' && !clearing) fireLaser();
    }
    if (clearing) {
      clearT -= dt;
      if (Math.random() < dt * 6) burst(rand(FX0 + 60, FX1 - 60), rand(120, 420), 12);
      if (clearT <= 0) {
        clearing = false;
        if (mode === 'game') showResults(); else startDemoLevel((demoLevel + 1) % LEVELS.length);
      }
    }
    if (overT >= 0) { overT -= dt; if (overT < 0) showGameOver(); }
  }
  function levelCleared() {
    if (clearing || overT >= 0) return;
    clearing = true; clearT = mode === 'game' ? 1.4 : 1.5;
    introT = -1; show('banner', false);
    for (const b of balls) { burst(b.x, b.y, 10); b.dead = true; }
    clearDrops(); clearLasers();
    for (const k in eff) eff[k] = 0;
    if (mode === 'game') { Snd.stopSong(); Snd.sfx.clear(); mascotMood('happy', 3); }
  }
  function ballsLost() {
    if (mode === 'demo') { resetServe(); return; }
    lives--;
    combo = 0; lastTier = 1;
    for (const k in eff) eff[k] = 0;
    clearLasers();
    Snd.sfx.lose();
    shake(0.35, 7);
    heartT = 0.6;
    mascotMood('sad', 1.8);
    if (lives <= 0) { lives = 0; overT = 1.3; toast(S.oops); }
    else { resetServe(); toast(S.oops + ' ' + (lives === 1 ? S.lastLife : F(S.livesLeft, { n: lives }))); }
  }

  // ================= rendering =================
  function renderWorld(dt) {
    for (const k of bricks) {
      if (!k.alive) continue;
      let dirty = k.mv >= 0;
      if (k.wob < 0.8) { k.wob += dt; dirty = true; }
      if (!dirty) continue;
      if (k.wob < 0.8) {
        const a = 0.2 * k.wobA * Math.exp(-k.wob * 6.5) * Math.cos(k.wob * 30);
        const sx = k.wobV ? 1 + a : 1 - a, sy = k.wobV ? 1 - a : 1 + a;
        k.g.setAttribute('transform', 'translate(' + r1(k.x) + ',' + k.y + ') scale(' + r3(sx) + ',' + r3(sy) + ')');
        k.flash.setAttribute('opacity', r3(Math.max(0, 0.65 - k.wob * 5) * (k.wobA >= 1 ? 1 : 0.3)));
      } else {
        k.g.setAttribute('transform', 'translate(' + r1(k.x) + ',' + k.y + ')');
        k.flash.setAttribute('opacity', 0);
      }
    }
    const fire = eff.fire > 0;
    for (const b of balls) {
      const v = b.vis;
      if (v.fire !== fire) {
        v.fire = fire;
        v.body.setAttribute('fill', fire ? 'url(#g-bean-fire)' : 'url(#g-bean)');
        v.body.setAttribute('stroke', fire ? '#e0521f' : '#c23a78');
        show(v.glow, fire);
      }
      b.sq = Math.max(0, b.sq - dt * 5);
      const ang = b.stuck ? -90 + Math.sin(T * 5) * 10 : Math.atan2(b.vy, b.vx) * 57.2958;
      const s = 1 + b.sq * 0.3;
      v.g.setAttribute('transform', 'translate(' + r1(b.x) + ',' + r1(b.y) + ')');
      v.inner.setAttribute('transform', 'rotate(' + (ang | 0) + ') scale(' + r3(s) + ',' + r3(2 - s) + ')');
      if (b.stuck) b.hist.length = 0;
      else if (dt > 0) {
        b.hist.unshift(b.x, b.y);
        if (b.hist.length > (TRAIL_N + 1) * 2) b.hist.length = (TRAIL_N + 1) * 2;
      }
      const n = b.hist.length / 2 - 1;
      for (let j = 0; j < TRAIL_N; j++) {
        const l = v.trail[j];
        if (j >= n) { if (l.__on) { l.__on = false; l.style.display = 'none'; } continue; }
        if (!l.__on) { l.__on = true; l.style.display = ''; }
        const k = j / TRAIL_N;
        l.setAttribute('x1', r1(b.hist[j * 2])); l.setAttribute('y1', r1(b.hist[j * 2 + 1]));
        l.setAttribute('x2', r1(b.hist[j * 2 + 2])); l.setAttribute('y2', r1(b.hist[j * 2 + 3]));
        l.setAttribute('stroke-width', r1(R * 1.75 * (1 - k) + 1.5));
        l.setAttribute('stroke', fire ? 'hsl(' + ((42 - j * 3) | 0) + ',100%,' + ((62 - j) | 0) + '%)' : 'hsl(' + (((T * 220 + j * 26) % 360) | 0) + ',95%,72%)');
        l.setAttribute('opacity', r3(0.85 * (1 - k)));
      }
    }
    renderPaddle();
    if (shakeT > 0) {
      shakeT = Math.max(0, shakeT - dt);
      const a = shakeA * (shakeT > 0 ? 1 : 0) * Math.min(1, shakeT * 4);
      world.setAttribute('transform', 'translate(' + r1(rand(-a, a)) + ',' + r1(rand(-a, a)) + ')');
      if (shakeT <= 0) { shakeA = 0; world.removeAttribute('transform'); }
    }
  }

  // ================= HUD =================
  const H = {};
  const pwRows = [];
  function buildHUD() {
    H.score = $('hud-score'); H.best = $('hud-best'); H.level = $('hud-level'); H.lvname = $('hud-lvname');
    H.diff = $('hud-diff'); H.time = $('hud-time'); H.combo = $('hud-combo'); H.mult = $('hud-mult');
    H.gauge = $('hud-gauge'); H.maxc = $('hud-maxc'); H.pwNone = $('pw-none');
    H.hearts = [];
    const lg = $('hud-lives');
    for (let i = 0; i < 3; i++) {
      const g = mk('g', { transform: 'translate(' + ((i - 1) * 56) + ',0)' }, lg);
      const inner = mk('g', null, g);
      mk('path', { d: HEART, transform: 'translate(1.5,3)', fill: '#b0336a', opacity: 0.18 }, inner);
      const body = mk('path', { d: HEART, fill: 'url(#gb-R)', stroke: '#d6385a', 'stroke-width': 2 }, inner);
      const hl = mk('ellipse', { cx: -6, cy: -8, rx: 4.5, ry: 2.8, fill: '#fff', opacity: 0.8 }, inner);
      H.hearts.push({ g: g, inner: inner, body: body, hl: hl, on: null });
    }
    const list = $('pw-list');
    for (let i = 0; i < 5; i++) {
      const g = mk('g', { transform: 'translate(0,' + (i * 38) + ')', style: 'display:none' }, list);
      const icon = mk('g', { transform: 'translate(40,14) scale(0.72)' }, g);
      const name = txt(g, 72, 13, '', { 'font-size': 14, 'font-weight': 700, class: 'berry' });
      const sec = txt(g, 206, 13, '', { 'font-size': 14, 'font-weight': 900, 'text-anchor': 'end', fill: '#ff5c9d' });
      mk('rect', { x: 72, y: 19, width: 134, height: 7, rx: 3.5, fill: '#f3e3ec' }, g);
      const bar = mk('rect', { x: 72, y: 19, width: 134, height: 7, rx: 3.5, fill: '#ff8fbd' }, g);
      pwRows.push({ g: g, icon: icon, name: name, sec: sec, bar: bar, type: null, on: false });
    }
  }
  let gaugeW = 0, comboBump = 0, lastComboShown = -1;
  function renderHUD(dt) {
    if (mode !== 'game') return;
    shownScore = Math.abs(score - shownScore) < 1 ? score : lerp(shownScore, score, Math.min(1, dt * 9));
    setText(H.score, fmt(shownScore));
    setText(H.best, F(S.hudBest, { n: fmt(Math.max(save.best[diffKey] || 0, score)) }));
    setText(H.level, (levelIdx + 1) + ' / ' + LEVELS.length);
    setText(H.lvname, LEVELS[levelIdx].name);
    setText(H.diff, F(S.diffLabel, { d: DIFF[diffKey].name }));
    const rem = Math.max(0, levelPar - levelTime);
    setText(H.time, F(S.hudTime, { t: Math.floor(rem / 60) + ':' + String(Math.floor(rem % 60)).padStart(2, '0') }));
    if (combo !== lastComboShown) { if (combo > lastComboShown && combo > 0) comboBump = 1; lastComboShown = combo; setText(H.combo, combo); }
    comboBump = Math.max(0, comboBump - dt * 4);
    H.combo.setAttribute('transform', comboBump > 0 ? 'translate(112,82) scale(' + r3(1 + comboBump * 0.25) + ') translate(-112,-82)' : '');
    const m = comboMult();
    setText(H.mult, F(S.mult, { n: m }));
    const gw = m >= 8 ? 184 : ((combo % 4) / 4) * 184;
    gaugeW = lerp(gaugeW, gw, Math.min(1, dt * 12));
    H.gauge.setAttribute('width', r1(gaugeW));
    setText(H.maxc, F(S.hudMaxCombo, { n: maxCombo }));
    heartT = Math.max(0, heartT - dt);
    for (let i = 0; i < 3; i++) {
      const h = H.hearts[i], on = i < lives;
      if (h.on !== on) {
        h.on = on;
        h.body.setAttribute('fill', on ? 'url(#gb-R)' : '#f1e3ea');
        h.body.setAttribute('stroke', on ? '#d6385a' : '#d9bccb');
        h.hl.setAttribute('opacity', on ? 0.8 : 0.3);
      }
      const bob = on ? Math.sin(T * 3 + i * 0.9) * 2 : 0;
      const sc = !on && heartT > 0 && i === lives ? 1 + heartT * 0.6 : 1;
      h.inner.setAttribute('transform', 'translate(0,' + r1(bob) + ') scale(' + r3(sc) + ')');
    }
    const act = TIMED.filter((k) => eff[k] > 0);
    for (let i = 0; i < pwRows.length; i++) {
      const row = pwRows[i], k = act[i];
      if (!k) { if (row.on) { row.on = false; show(row.g, false); } continue; }
      if (!row.on) { row.on = true; show(row.g, true); }
      if (row.type !== k) {
        row.type = k;
        while (row.icon.firstChild) row.icon.removeChild(row.icon.firstChild);
        dropArt(row.icon, k, 1);
        setText(row.name, DROPS[k].name);
        row.bar.setAttribute('fill', DROPS[k].base);
      }
      setText(row.sec, F(S.secs, { n: Math.ceil(eff[k]) }));
      row.bar.setAttribute('width', r1(Math.max(0, 134 * eff[k] / DROPS[k].dur)));
    }
    show(H.pwNone, act.length === 0);
  }

  // ================= UI screens =================
  const BTN = {};
  function makeButton(parent, id, x, y, w, h, label, col, fs) {
    const g = mk('g', { id: id, class: 'btn', transform: 'translate(' + x + ',' + y + ')' }, parent);
    const inner = mk('g', null, g);
    mk('rect', { x: -w / 2, y: -h / 2 + 5, width: w, height: h, rx: h / 2, fill: col.deep }, inner);
    mk('rect', { x: -w / 2, y: -h / 2, width: w, height: h, rx: h / 2, fill: col.base, stroke: '#fff', 'stroke-width': 3 }, inner);
    mk('rect', { x: -w / 2 + 14, y: -h / 2 + 5, width: w - 28, height: h * 0.28, rx: h * 0.14, fill: '#fff', opacity: 0.35 }, inner);
    txt(inner, 0, fs * 0.36, label, { 'text-anchor': 'middle', 'font-size': fs, 'font-weight': 900, fill: '#fff', stroke: col.deep, 'stroke-width': 4, 'paint-order': 'stroke', 'stroke-linejoin': 'round' });
    const sel = mk('rect', { x: -w / 2 - 7, y: -h / 2 - 7, width: w + 14, height: h + 19, rx: (h + 14) / 2, fill: 'none', stroke: '#ff5c9d', 'stroke-width': 3, 'stroke-dasharray': '9 5', class: 'ring-dash', opacity: 0 }, g);
    BTN[id] = { g: g, inner: inner, sel: sel, on: false };
    g.addEventListener('pointerenter', () => {
      if (!menu) return;
      const i = MENUS[menu].indexOf(id);
      if (i >= 0 && i !== menuSel) { menuSel = i; refreshMenu(); Snd.sfx.tick(); }
    });
    g.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!menu || MENUS[menu].indexOf(id) < 0) return;
      menuSel = MENUS[menu].indexOf(id);
      menuOk();
    });
    return g;
  }
  const MENUS = {
    title: ['diff', 'b-start', 'b-help'],
    pause: ['b-resume', 'b-restart', 'b-quit'],
    over: ['b-again1', 'b-title1'],
    end: ['b-again2', 'b-title2'],
  };
  const ACT = {
    diff: () => { menuSel = 1; refreshMenu(); },
    'b-start': () => startGame(),
    'b-help': () => openHelp('title'),
    'b-resume': () => resumeGame(),
    'b-restart': () => restartLevel(),
    'b-quit': () => goTitle(),
    'b-again1': () => startGame(),
    'b-title1': () => goTitle(),
    'b-again2': () => startGame(),
    'b-title2': () => goTitle(),
  };
  function setMenu(name, sel) { menu = name; menuSel = sel || 0; refreshMenu(); }
  function refreshMenu() {
    for (const id in BTN) {
      const on = !!menu && MENUS[menu][menuSel] === id;
      const b = BTN[id];
      if (b.on === on) continue;
      b.on = on;
      if (on) b.inner.setAttribute('transform', 'scale(1.07)'); else b.inner.removeAttribute('transform');
      b.sel.setAttribute('opacity', on ? 1 : 0);
    }
    show('diff-ring', menu === 'title' && MENUS.title[menuSel] === 'diff');
  }
  function menuMove(d) {
    if (!menu) return;
    const n = MENUS[menu].length;
    menuSel = (menuSel + d + n) % n;
    refreshMenu();
    Snd.sfx.tick();
  }
  function menuOk() {
    if (!menu) return;
    if ((state === 'over' || state === 'end') && screenT < 0.7) return;
    const id = MENUS[menu][menuSel];
    Snd.sfx.select();
    ACT[id]();
  }
  const diffPills = {};
