    for (let i = 0; i < 4; i++) mk('path', { d: 'M0,0 C10,-26 42,-30 50,-6', transform: 'rotate(' + i * 90 + ')', fill: 'none', stroke: sw[i], 'stroke-width': 9, 'stroke-linecap': 'round' }, disc);
    mk('circle', { r: 9, fill: '#fff' }, disc);
