  function dropLikeCandy(g) {
    mk('path', { d: 'M-40,-8 L-66,-26 Q-74,0 -66,26 L-40,8 Z', fill: '#c9f7e6', stroke: '#23a077', 'stroke-width': 3, 'stroke-linejoin': 'round' }, g);
    mk('path', { d: 'M40,-8 L66,-26 Q74,0 66,26 L40,8 Z', fill: '#c9f7e6', stroke: '#23a077', 'stroke-width': 3, 'stroke-linejoin': 'round' }, g);
    mk('ellipse', { rx: 46, ry: 32, fill: '#57d3a7', stroke: '#23a077', 'stroke-width': 3 }, g);
    for (let i = -2; i <= 2; i++) mk('path', { d: 'M' + (i * 16 - 8) + ',-30 Q' + (i * 16 + 6) + ',0 ' + (i * 16 - 8) + ',30', stroke: '#fff', 'stroke-width': 5, fill: 'none', opacity: 0.7 }, g);
    mk('ellipse', { cx: -16, cy: -14, rx: 12, ry: 6, fill: '#fff', opacity: 0.7 }, g);
  }
  function buildMascot(parent, x, y, s) {
    const g = mk('g', { transform: 'translate(' + x + ',' + y + ') scale(' + s + ')' }, parent);
    mk('ellipse', { cx: 0, cy: 64, rx: 62, ry: 11, fill: '#c2366f', opacity: 0.16 }, g);
    const b = mk('g', { class: 'bob2' }, g);
    ['#ff9ec4', '#ffd08a', '#fff09a', '#a8ecd0', '#a8d8ff', '#d4c2ff'].forEach((c, i) => {
      mk('path', { d: 'M-128,' + (30 + i * 7) + ' Q-96,' + (4 + i * 7) + ' -64,' + (18 + i * 7), stroke: c, 'stroke-width': 7, fill: 'none', 'stroke-linecap': 'round' }, b);
    });
    mk('path', { d: BEAN, transform: 'scale(6.4)', fill: 'url(#g-bean)', stroke: '#c23a78', 'stroke-width': 0.55 }, b);
    mk('path', { d: BEAN_HL, transform: 'scale(6.4)', fill: '#fff', opacity: 0.85 }, b);
    const ink = { stroke: '#4a1d38', 'stroke-width': 3.6, fill: 'none', 'stroke-linecap': 'round' };
    const faces = { normal: mk('g', null, b), happy: mk('g', { style: 'display:none' }, b), sad: mk('g', { style: 'display:none' }, b) };
    for (const sx of [-1, 1]) {
      mk('ellipse', { cx: sx * 40, cy: 20, rx: 10, ry: 5.5, fill: '#ff4f93', opacity: 0.45 }, b);
      mk('ellipse', { cx: sx * 21, cy: 4, rx: 7, ry: 10, fill: '#4a1d38' }, faces.normal);
      mk('circle', { cx: sx * 21 - 2, cy: -1, r: 3, fill: '#fff' }, faces.normal);
      mk('circle', { cx: sx * 21 + 2.5, cy: 8, r: 1.4, fill: '#fff' }, faces.normal);
      mk('path', Object.assign({ d: 'M' + (sx * 21 - 8) + ',7 Q' + (sx * 21) + ',-5 ' + (sx * 21 + 8) + ',7', 'stroke-width': 4.2 }, ink), faces.happy);
      mk('path', Object.assign({ d: 'M' + (sx * 21 - 7) + ',2 Q' + (sx * 21) + ',9 ' + (sx * 21 + 7) + ',2', 'stroke-width': 4 }, ink), faces.sad);
    }
    mk('path', Object.assign({ d: 'M-9,18 Q0,28 9,18' }, ink), faces.normal);
    mk('path', { d: 'M-11,15 Q0,34 11,15 Z', fill: '#4a1d38' }, faces.happy);
    mk('ellipse', { cx: 0, cy: 25, rx: 5, ry: 3, fill: '#ff7fae' }, faces.happy);
    mk('path', Object.assign({ d: 'M-8,25 Q0,17 8,25' }, ink), faces.sad);
    mk('path', { d: 'M-27,10 Q-31,18 -27,21 Q-23,18 -27,10 Z', fill: '#7fd0ff', stroke: '#4a9ee0', 'stroke-width': 1.2 }, faces.sad);
    mk('path', { d: 'M62,4 Q84,-10 80,-30', stroke: '#c23a78', 'stroke-width': 8, fill: 'none', 'stroke-linecap': 'round' }, b);
    mk('circle', { cx: 80, cy: -32, r: 7, fill: '#ff8fbd', stroke: '#c23a78', 'stroke-width': 3 }, b);
    return { g: g, body: b, faces: faces };
  }
  const mini = { mood: 'normal', t: 0 };
  function buildMiniMascot() {
    const m = buildMascot($('hud'), 136, 588, 0.6);
    mini.g = m.g; mini.body = m.body; mini.faces = m.faces;
    mini.body.removeAttribute('class');
  }
  function mascotMood(mood, dur) {
    if (!mini.faces) return;
    if (mini.mood === 'sad' && mood === 'happy' && mini.t > 0.6) return;
    mini.mood = mood; mini.t = dur;
    for (const k in mini.faces) show(mini.faces[k], k === mood);
  }
  function renderMascot(dt) {
    if (!mini.body || mode !== 'game') return;
    if (mini.t > 0) { mini.t -= dt; if (mini.t <= 0 && state !== 'over') mascotMood('normal', 0); }
    let tr;
    if (mini.mood === 'happy') tr = 'translate(0,' + r1(-Math.abs(Math.sin(T * 11)) * 16) + ')';
    else if (mini.mood === 'sad') tr = 'translate(0,6) scale(1.05,0.93)';
    else tr = 'translate(0,' + r1(Math.sin(T * 2.6) * 4) + ')';
    mini.body.setAttribute('transform', tr);
  }
  let tipIdx = 0, tipT = 0;
  function refreshTitle() {
    DIFF_KEYS.forEach((k) => {
      const p = diffPills[k], on = k === diffKey, D = DIFF[k];
      p.bg.setAttribute('fill', on ? D.base : '#ffffff');
      p.bg.setAttribute('stroke', on ? '#ffffff' : D.base);
      p.t.setAttribute('fill', on ? '#ffffff' : D.deep);
      p.g.setAttribute('transform', 'translate(' + ((DIFF_KEYS.indexOf(k) - 1) * 128) + ',352)' + (on ? ' scale(1.06)' : ''));
    });
    setText($('diff-desc'), DIFF[diffKey].desc);
    setText($('title-best'), F(S.titleBest, { d: DIFF[diffKey].name, n: fmt(save.best[diffKey] || 0) }));
    DIFF_KEYS.forEach((k) => setText(H.board[k], fmt(save.best[k] || 0)));
  }
  function setTip(i) {
    const t = S['tip' + (i + 1)].split('/');
    setText(H.tip1, t[0]); setText(H.tip2, t[1] || '');
  }
  function changeDiff(d) {
    const i = DIFF_KEYS.indexOf(diffKey);
    diffKey = DIFF_KEYS[clamp(i + d, 0, 2)];
    save.diff = diffKey; persist();
    refreshTitle(); Snd.sfx.tick();
  }
  function buildHelp() {
    const body = $('help-body');
    function head(x, y, s, col) {
      const w = s.length * 20 + 40;
      mk('rect', { x: x - w / 2, y: y - 18, width: w, height: 34, rx: 17, fill: col }, body);
      txt(body, x, y + 6, s, { 'text-anchor': 'middle', 'font-size': 18, 'font-weight': 900, fill: '#fff' });
    }
    function chip(x, y, label, w) {
      w = w || 34;
      mk('rect', { x: x, y: y - 16, width: w, height: 30, rx: 8, fill: '#fff', stroke: '#e0a3c0', 'stroke-width': 2 }, body);
      mk('rect', { x: x, y: y + 10, width: w, height: 4, rx: 2, fill: '#e0a3c0' }, body);
      if (label === '<' || label === '>') {
        const cx = x + w / 2, s = label === '<' ? -1 : 1;
        mk('path', { d: 'M' + (cx - 5 * s) + ',' + (y - 7) + ' L' + (cx + 6 * s) + ',' + (y - 1) + ' L' + (cx - 5 * s) + ',' + (y + 5) + ' Z', fill: '#7a2e57' }, body);
      } else txt(body, x + w / 2, y + 5, label, { 'text-anchor': 'middle', 'font-size': 15, 'font-weight': 900, class: 'berry' });
      return x + w + 6;
    }
    head(300, 164, S.helpCtrl, '#ff8fbd');
    head(640, 164, S.helpBricks, '#57d3a7');
    head(985, 164, S.helpItems, '#ff9f6e');
    const lab = { 'font-size': 16, 'font-weight': 700, class: 'berry' };
    let x = chip(150, 214, '<'); x = chip(x, 214, '>');
    txt(body, x + 2, 219, '/', lab); x = chip(x + 16, 214, 'A'); x = chip(x, 214, 'D');
    txt(body, 340, 219, S.hk1, lab);
    chip(150, 260, S.keyMouse, 60); txt(body, 340, 265, S.hk2, lab);
    x = chip(150, 306, S.keySpace, 60); txt(body, x + 2, 311, '/', lab); chip(x + 16, 306, S.keyClick, 60);
    txt(body, 340, 311, S.hk3, lab);
    chip(150, 352, 'P'); txt(body, 192, 357, S.hk4, lab);
    chip(250, 352, 'H'); txt(body, 292, 357, S.hk5, lab);
    chip(350, 352, 'M'); txt(body, 392, 357, S.hk6, lab);
    head(300, 412, S.helpRules, '#a98bff');
    [S.rule1, S.rule2, S.rule3, S.rule4].forEach((r, i) => {
      const y = 456 + i * 34;
      mk('circle', { cx: 160, cy: y - 5, r: 5, fill: ['#ff8fbd', '#6fe0b9', '#ffd86e', '#b9a0ff'][i] }, body);
      txt(body, 174, y, r, { 'font-size': 15, class: 'berry' });
    });
    const bricksInfo = [['normal', 'P', 1, S.bNormal, S.bNormalD], ['hard', 'M', 2, S.bHard, S.bHardD], ['choco', 'X', 1, S.bChoco, S.bChocoD], ['pop', '*', 1, S.bPop, S.bPopD], ['gift', '@', 1, S.bGift, S.bGiftD]];
    bricksInfo.forEach((b, i) => {
      const y = 222 + i * 84;
      const g = mk('g', { transform: 'translate(530,' + y + ') scale(1.4)' }, body);
      const o = brickArt(g, b[0], b[1], b[2]);
      if (o.cracks) show(o.cracks[0], true);
      if (b[0] === 'hard') {
        const g2 = mk('g', { transform: 'translate(588,' + y + ') scale(1.4)' }, body);
        const o2 = brickArt(g2, 'hard', '3', 3);
        show(o2.cracks[1], true);
      }
      const tx = b[0] === 'hard' ? 626 : 572;
      txt(body, tx, y - 3, b[3], { 'font-size': 18, 'font-weight': 900, class: 'berry' });
      txt(body, tx, y + 19, b[4], { 'font-size': 13.5, class: 'dim' });
    });
    DROP_ORDER.forEach((k, i) => {
      const y = 214 + i * 55;
      const D = DROPS[k];
      const g = mk('g', { transform: 'translate(866,' + y + ')' }, body);
      dropArt(g, k, 0.95);
      txt(body, 906, y - 3, D.name, { 'font-size': 16, 'font-weight': 900, fill: D.good ? '#7a2e57' : '#5a3044' });
      txt(body, 906, y + 16, D.desc, { 'font-size': 13, class: 'dim' });
      const tg = D.good ? S.good : S.bad;
      mk('rect', { x: 1080, y: y - 18, width: 58, height: 22, rx: 11, fill: D.good ? '#d9f7ec' : '#eee3f2' }, body);
      txt(body, 1109, y - 2, tg, { 'text-anchor': 'middle', 'font-size': 12, 'font-weight': 700, fill: D.good ? '#1f9a72' : '#6a4a7a' });
    });
  }
  function buildEndCrown() {
    const g = mk('g', { class: 'bob' }, $('end-crown'));
    mk('path', { d: 'M-62,26 L-70,-22 L-36,2 L0,-34 L36,2 L70,-22 L62,26 Z', fill: '#ffd86e', stroke: '#e0a52a', 'stroke-width': 4, 'stroke-linejoin': 'round' }, g);
    mk('rect', { x: -64, y: 20, width: 128, height: 16, rx: 8, fill: '#ff8fbd', stroke: '#dd4f8b', 'stroke-width': 3 }, g);
    [[-70, -22, '#6fe0b9'], [0, -34, '#ff7088'], [70, -22, '#b9a0ff']].forEach((p) => mk('circle', { cx: p[0], cy: p[1], r: 8, fill: p[2], stroke: '#fff', 'stroke-width': 3 }, g));
    [[-34, 28, '#88cefb'], [0, 28, '#fff'], [34, 28, '#ffd86e']].forEach((p) => mk('circle', { cx: p[0], cy: p[1], r: 4.5, fill: p[2] }, g));
    mk('ellipse', { cx: -24, cy: -2, rx: 10, ry: 5, fill: '#fff', opacity: 0.7 }, g);
  }
  const endFx = makePool($('end-fx'), 160);
  let endBurstT = 0;

  function toast(s) {
    setText($('toast-t'), s);
    const w = Math.max(180, Array.from(s).length * 20 + 56);
    $('toast-bg').setAttribute('x', -w / 2); $('toast-bg').setAttribute('width', w);
    toastT = 0; show('toast', true);
  }
  let res = null, resT = 0;
  const clearRowEls = [];
  function buildClearRows() {
    const g = $('clear-rows');
    const defsRows = [[S.rowBricks, 268], [S.rowCombo, 330], [S.rowTime, 392]];
    defsRows.forEach((d) => {
      const row = mk('g', { style: 'display:none' }, g);
      txt(row, 444, d[1], d[0], { 'font-size': 19, 'font-weight': 900, class: 'berry' });
      const det = txt(row, 444, d[1] + 22, '', { 'font-size': 13.5, class: 'dim' });
      const val = txt(row, 836, d[1] + 4, '', { 'text-anchor': 'end', 'font-size': 26, 'font-weight': 900, fill: '#ff5c9d' });
      clearRowEls.push({ row: row, det: det, val: val });
    });
    const tot = mk('g', { style: 'display:none' }, g);
    mk('path', { d: 'M436,436 H844', stroke: '#ffc2da', 'stroke-width': 3, 'stroke-dasharray': '2 8', 'stroke-linecap': 'round' }, tot);
    txt(tot, 444, 484, S.rowTotal, { 'font-size': 21, 'font-weight': 900, class: 'berry' });
    const tv = txt(tot, 836, 488, '', { 'text-anchor': 'end', 'font-size': 36, 'font-weight': 900, fill: '#8466e6', stroke: '#fff', 'stroke-width': 4, 'paint-order': 'stroke' });
    const sc = txt(tot, 640, 526, '', { 'text-anchor': 'middle', 'font-size': 15, class: 'dim' });
    clearRowEls.push({ row: tot, val: tv, det: sc });
  }
  function showResults() {
    state = 'clear'; screenT = 0;
    const timeLeft = Math.max(0, Math.ceil(levelPar - levelTime));
    res = { brick: levelScore, combo: maxCombo, comboBonus: maxCombo * 100, timeLeft: timeLeft, timeBonus: timeLeft * 20 };
    res.total = res.brick + res.comboBonus + res.timeBonus;
    score += res.comboBonus + res.timeBonus;
    recordBest();
    setText($('clear-title'), F(S.clearTitle, { n: levelIdx + 1 }));
    setText($('clear-name'), LEVELS[levelIdx].name);
    setText($('clear-next'), levelIdx + 1 >= LEVELS.length ? S.clearLast : S.clearNext);
    setText(clearRowEls[1].det, F(S.rowComboD, { n: res.combo }));
    setText(clearRowEls[2].det, F(S.rowTimeD, { n: res.timeLeft }));
    setText(clearRowEls[3].det, F(S.rowScore, { n: fmt(score) }));
    for (const r of clearRowEls) { r.shown = false; show(r.row, false); }
    resT = 0;
    show('scr-clear', true);
    menu = null; refreshMenu();
  }
  function renderResults(dt) {
    if (state !== 'clear' || !res) return;
    const prev = resT;
    resT += dt;
    const vals = [res.brick, res.comboBonus, res.timeBonus, res.total];
    for (let i = 0; i < 4; i++) {
      const t0 = 0.3 + i * 0.45;
      const el = clearRowEls[i];
      if (resT < t0) continue;
      if (!el.shown) { el.shown = true; show(el.row, true); Snd.sfx.tick(); }
      const k = clamp((resT - t0) / 0.4, 0, 1);
      setText(el.val, (i < 3 ? '+' : '') + fmt(vals[i] * k));
    }
    if (prev < 2.1 && resT >= 2.1) burst(640, 470, 26);
    if (autoPlay && resT > 2.8) clearContinue();
  }
  function clearContinue() {
    if (resT < 2.1) { resT = 2.1; return; }
    show('scr-clear', false);
    if (levelIdx + 1 >= LEVELS.length) showEnding();
    else { levelIdx++; beginLevel(); }
  }
  function renderUI(dt) {
    const banner = $('banner');
    if (introT >= 0) {
      if (state === 'play') introT += dt;
      const t = introT;
      let x = 0, op = 1;
      if (t < 0.5) x = lerp(-760, 0, easeOutBack(t / 0.5));
      else if (t > 2.2 && t < 2.6) { const k = (t - 2.2) / 0.4; x = lerp(0, 820, easeInCubic(k)); op = 1 - k; }
      if (t >= 2.6) { introT = -1; show(banner, false); }
      else { banner.setAttribute('transform', 'translate(' + r1(640 + x) + ',318)'); banner.setAttribute('opacity', r3(op)); }
    }
    const stuck = state === 'play' && mode === 'game' && !autoPlay && !clearing && overT < 0 && balls.some((b) => b.stuck);
    show('serve-tip', stuck && (introT < 0 || introT > 1.0));
    if (toastT >= 0) {
      toastT += dt;
      const tg = $('toast');
      const y = state === 'title' ? 650 : 540;
      if (toastT > 1.8) { toastT = -1; show(tg, false); }
      else {
        const s = toastT < 0.2 ? easeOutBack(toastT / 0.2) : 1;
        tg.setAttribute('transform', 'translate(640,' + y + ') scale(' + r3(Math.max(0.01, s)) + ')');
        tg.setAttribute('opacity', r3(toastT > 1.5 ? 1 - (toastT - 1.5) / 0.3 : 1));
      }
    }
    if (comboT >= 0) {
      comboT += dt;
      const cp = $('combo-pop');
      if (comboT > 1.0 || state !== 'play') { comboT = -1; show(cp, false); }
      else {
        const s = comboT < 0.25 ? easeOutBack(comboT / 0.25) : 1 + (comboT - 0.25) * 0.1;
        cp.setAttribute('transform', 'translate(640,' + r1(500 - comboT * 30) + ') scale(' + r3(Math.max(0.01, s)) + ')');
        cp.setAttribute('opacity', r3(comboT > 0.7 ? 1 - (comboT - 0.7) / 0.3 : 1));
      }
    }
    if (state === 'title' || (state === 'help' && helpFrom === 'title')) {
      tipT += dt;
      if (tipT > 4.5) { tipT = 0; tipIdx = (tipIdx + 1) % 6; setTip(tipIdx); }
    }
    renderResults(dt);
    screenT += dt;
    if (state === 'end') {
      endBurstT -= dt;
      if (endBurstT <= 0) {
        endBurstT = rand(0.35, 0.7);
        const bx = Math.random() < 0.5 ? rand(80, 360) : rand(920, 1200);
        burst(bx, rand(90, 420), 26, endFx);
      }
    }
    endFx.update(dt);
  }

  // ================= flow =================
  function hideScreens() { for (const s of ['scr-title', 'scr-help', 'scr-pause', 'scr-clear', 'scr-over', 'scr-end']) show(s, false); }
  function startDemoLevel(i) {
    demoLevel = i;
    loadLevel(i);
    clearDrops(); clearLasers();
    for (const k in eff) eff[k] = 0;
    clearing = false; overT = -1;
    resetServe();
  }
  function goTitle() {
    if (mode === 'game') recordBest();
    hideScreens();
    show('hud', false); show('scr-title', true); show('banner', false); show('combo-pop', false);
    introT = -1; comboT = -1;
    mode = 'demo'; state = 'title'; autoPlay = false;
    fx.clear(); endFx.clear();
    pad.w = DIFF.normal.paddle;
    startDemoLevel((Math.random() * LEVELS.length) | 0);
    setMenu('title', 1);
    refreshTitle();
    Snd.playSong('title');
    svg.style.cursor = '';
  }
  function startGame() {
    hideScreens();
    show('hud', true);
    mode = 'game';
    score = 0; shownScore = 0; lives = 3; levelIdx = 0;
    bestAtStart = save.best[diffKey] || 0;
    save.diff = diffKey; persist();
    fx.clear(); endFx.clear();
    beginLevel();
  }
  function beginLevel() {
    state = 'play'; clearing = false; overT = -1;
    loadLevel(levelIdx);
    for (const k in eff) eff[k] = 0;
    clearDrops(); clearLasers();
    pad.x = 640; pad.w = DIFF[diffKey].paddle; pad.bend = 0; pad.bendV = 0;
    resetServe();
    combo = 0; maxCombo = 0; lastTier = 1; levelTime = 0; levelScore = 0; speedRamp = 0;
    levelPar = Math.round(LEVELS[levelIdx].par * DIFF[diffKey].par);
    levelStartScore = score; levelStartLives = lives;
    setText($('banner-no'), F(S.stageNo, { n: levelIdx + 1 }));
    setText($('banner-name'), LEVELS[levelIdx].name);
    setText($('banner-tip'), LEVELS[levelIdx].tip);
    introT = 0; show('banner', true);
    mascotMood('normal', 0);
    menu = null; refreshMenu();
    Snd.duck(1);
    Snd.playSong('game');
  }
  function pauseGame() {
    if (state !== 'play') return;
    state = 'pause';
    show('scr-pause', true);
    setMenu('pause', 0);
    keys.left = keys.right = keys.fire = false; mouseHeld = false;
    Snd.duck(0.35);
  }
  function resumeGame() {
    state = 'play';
    show('scr-pause', false);
    menu = null; refreshMenu();
    Snd.duck(1);
  }
  function restartLevel() {
    show('scr-pause', false);
    score = levelStartScore; shownScore = score; lives = levelStartLives;
    beginLevel();
  }
  function openHelp(from) {
    helpFrom = from;
    state = 'help';
    show('scr-pause', false);
    show('scr-help', true);
  }
  function closeHelp() {
    show('scr-help', false);
    if (helpFrom === 'pause') { state = 'pause'; show('scr-pause', true); refreshMenu(); }
    else { state = 'title'; setMenu('title', menuSel); }
  }
  function recordBest() {
    if (score > (save.best[diffKey] || 0)) { save.best[diffKey] = score; persist(); }
  }
  function showGameOver() {
    state = 'over'; screenT = 0; overT = -1;
    recordBest();
    setText($('over-score'), fmt(score));
    setText($('over-best'), F(S.best, { n: fmt(save.best[diffKey] || 0) }));
    setText($('over-info'), F(S.overInfo, { n: levelIdx + 1, name: LEVELS[levelIdx].name }));
    show('over-rec', score > bestAtStart && score > 0);
    show('scr-over', true);
    mascotMood('sad', 99);
    setMenu('over', 0);
    Snd.stopSong(); Snd.sfx.over();
  }
  function showEnding() {
    state = 'end'; screenT = 0; endBurstT = 0.2;
    recordBest();
    setText($('end-score'), fmt(score));
    setText($('end-best'), F(S.best, { n: fmt(save.best[diffKey] || 0) }));
    setText($('end-info'), F(S.endInfo, { d: DIFF[diffKey].name }));
    show('end-rec', score > bestAtStart && score > 0);
    show('scr-end', true);
    setMenu('end', 0);
    Snd.stopSong(); Snd.sfx.win();
    setTimeout(() => { if (state === 'end') Snd.playSong('title'); }, 2600);
  }
  function primaryAction() {
    if (state !== 'play' || clearing || overT >= 0) return;
    if (releaseBalls()) return;
    fireLaser();
  }
  function toggleMute() {
    save.muted = !save.muted;
    Snd.setMuted(save.muted);
    persist();
    setText($('hud-sound-t'), save.muted ? S.soundOff : S.soundOn);
    toast(save.muted ? S.muted : S.unmuted);
  }

  // ================= input =================
  function onKeyDown(e) {
    const c = e.code, k = e.key;
    Snd.init();
    const isLeft = c === 'ArrowLeft' || c === 'KeyA', isRight = c === 'ArrowRight' || c === 'KeyD';
    const isUp = c === 'ArrowUp' || c === 'KeyW', isDown = c === 'ArrowDown' || c === 'KeyS';
    const isSpace = c === 'Space' || k === ' ';
    const isOk = c === 'Enter' || c === 'NumpadEnter' || isSpace;
    if (isLeft || isRight || isUp || isDown || isSpace) e.preventDefault();
    if (isLeft) keys.left = true;
    if (isRight) keys.right = true;
    if (c === 'KeyM') { if (!e.repeat) toggleMute(); return; }
    if (isSpace && state === 'play') keys.fire = true;
    if (e.repeat && (c === 'KeyP' || c === 'KeyH' || c === 'Escape' || isOk)) return;
    switch (state) {
      case 'title':
        if (isUp) menuMove(-1);
        else if (isDown) menuMove(1);
        else if (isLeft) changeDiff(-1);
        else if (isRight) changeDiff(1);
        else if (isOk) menuOk();
        else if (c === 'KeyH') openHelp('title');
        break;
      case 'help':
        if (c === 'KeyH' || c === 'Escape' || isOk) closeHelp();
        break;
      case 'play':
        if (c === 'KeyP' || c === 'Escape') pauseGame();
        else if (c === 'KeyH') { pauseGame(); openHelp('pause'); }
        else if (isOk) primaryAction();
        break;
      case 'pause':
        if (c === 'KeyP' || c === 'Escape') resumeGame();
        else if (c === 'KeyH') openHelp('pause');
        else if (isUp) menuMove(-1);
        else if (isDown) menuMove(1);
        else if (isOk) menuOk();
        break;
      case 'clear':
        if (isOk && screenT > 0.4) clearContinue();
        break;
      case 'over':
      case 'end':
        if (isUp || isLeft) menuMove(-1);
        else if (isDown || isRight) menuMove(1);
        else if (isOk) menuOk();
        break;
    }
  }
  function onKeyUp(e) {
    const c = e.code;
    if (c === 'ArrowLeft' || c === 'KeyA') keys.left = false;
    if (c === 'ArrowRight' || c === 'KeyD') keys.right = false;
    if (c === 'Space' || e.key === ' ') keys.fire = false;
  }
  const pt = svg.createSVGPoint();
  function toSvg(cx, cy) {
    pt.x = cx; pt.y = cy;
    const m = svg.getScreenCTM();
    return m ? pt.matrixTransform(m.inverse()) : { x: cx, y: cy };
  }
  svg.addEventListener('pointermove', (e) => {
    const p = toSvg(e.clientX, e.clientY);
    if (Math.abs(p.x - mouseX) > 0.5) { mouseX = p.x; if (state === 'play') inputMode = 'mouse'; }
    svg.style.cursor = state === 'play' && inputMode === 'mouse' ? 'none' : '';
  });
  svg.addEventListener('pointerdown', (e) => {
    Snd.init();
    if (e.button !== undefined && e.button !== 0) return;
    const onBtn = e.target && e.target.closest && e.target.closest('.btn');
    if (onBtn) return;
    if (state === 'play') {
      const p = toSvg(e.clientX, e.clientY);
      mouseX = p.x; inputMode = 'mouse';
      mouseHeld = true;
      primaryAction();
    } else if (state === 'help') closeHelp();
    else if (state === 'clear' && screenT > 0.4) clearContinue();
  });
  $('hud-pause').addEventListener('click', (e) => { e.stopPropagation(); Snd.init(); if (state === 'play') { Snd.sfx.select(); pauseGame(); } });
  $('hud-sound').addEventListener('click', (e) => { e.stopPropagation(); Snd.init(); toggleMute(); });
  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  window.addEventListener('pointerup', () => { mouseHeld = false; });
  window.addEventListener('blur', () => { keys.left = keys.right = keys.fire = false; mouseHeld = false; if (state === 'play' && mode === 'game') pauseGame(); });

  // ================= main loop =================
  let lastT = performance.now();
  function frame(now) {
    requestAnimationFrame(frame);
    let dt = (now - lastT) / 1000;
    lastT = now;
    if (!(dt >= 0)) dt = 0;
    if (dt > 0.05) dt = 0.05;
    T += dt;
    updateBackground(dt);
    const running = state === 'play' || state === 'title' || (state === 'help' && helpFrom === 'title');
    if (running) updateWorld(dt);
    const fxOn = state !== 'pause' && !(state === 'help' && helpFrom === 'pause');
    if (fxOn) { fx.update(dt); updateRings(dt); updatePops(dt); }
    renderWorld(running ? dt : 0);
    renderHUD(dt);
    renderMascot(dt);
    renderUI(dt);
  }

  // ================= boot =================
  buildBackground();
  buildPaddle();
  buildBallVisuals();
  buildHUD();
  buildMiniMascot();
  buildTitle();
  buildHelp();
  buildEndCrown();
  buildClearRows();
  setTip(0);
  Snd.setMuted(save.muted);
  setText($('hud-sound-t'), save.muted ? S.soundOff : S.soundOn);
  goTitle();
  requestAnimationFrame(frame);

  window.CB = {
    info() {
      return { state: state, mode: mode, diff: diffKey, level: levelIdx + 1, score: score, lives: lives, bricksLeft: breakableLeft, balls: balls.length, combo: combo, maxCombo: maxCombo, eff: Object.assign({}, eff), best: Object.assign({}, save.best), auto: autoPlay, audio: Snd.stateInfo() };
    },
    start(d) { if (d && DIFF[d]) diffKey = d; startGame(); return this.info(); },
    level(n) { if (mode !== 'game') startGame(); levelIdx = clamp((n | 0) - 1, 0, LEVELS.length - 1); hideScreens(); show('hud', true); beginLevel(); return this.info(); },
    clear() { for (const k of bricks) if (k.alive && k.type !== 'choco') { k.hp = 1; destroyBrick(k); } return this.info(); },
    thin(n) { const live = bricks.filter((k) => k.alive && k.type !== 'choco'); for (let i = 0; i < Math.min(n, live.length - 1); i++) destroyBrick(live[i]); combo = 0; lastTier = 1; return this.info(); },
    give(t) { applyDrop(t); return this.info(); },
    drop(t) { spawnDrop(pad.x + rand(-40, 40), 420, t); return this.info(); },
    lose() { for (const b of balls) b.dead = true; return this.info(); },
    launch() { releaseBalls(); return this.info(); },
    auto(on) { autoPlay = on !== false; return this.info(); },
  };
})();
